create index teams_event_id_division_id_fk_idx on public.teams (event_id, division_id);
create index teams_created_by_fk_idx on public.teams (created_by);

alter table public.teams enable row level security;
alter table public.team_members enable row level security;

create function private.hides_team_names(p_event uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    private.event_role(p_event) = 'judge'
      and not private.can_manage(p_event)
      and (private.event_setting(p_event, 'judging') ->> 'blind')::boolean,
    false
  );
$$;
grant execute on function private.hides_team_names(uuid) to anon, authenticated;

create policy teams_select on public.teams for select to anon, authenticated
  using (
    (select private.can_manage(event_id))
    or (
      (select private.has_permission(event_id, 'event.view'))
      and not (select private.hides_team_names(event_id))
    )
    or (
      (select private.is_public_event(event_id))
      and (select private.window_open(event_id, 'gallery'))
      and not (select private.hides_team_names(event_id))
    )
  );
create policy teams_manage_insert on public.teams for insert to authenticated
  with check ((select private.can_manage(event_id)));
create policy teams_update on public.teams for update to authenticated
  using (
    ((select private.can_manage(event_id)))
    or
    (
      locked_at is null
      and (select private.window_open(event_id, 'teams'))
      and (select private.network_allowed(event_id))
      and exists (
      select 1 from public.team_members tm
      where tm.team_id = teams.id and tm.user_id = (select auth.uid()) and tm.role = 'captain'
      )
    )
  )
  with check (
    ((select private.can_manage(event_id)))
    or
    (
      locked_at is null
      and (select private.window_open(event_id, 'teams'))
      and exists (
      select 1 from public.team_members tm
      where tm.team_id = teams.id and tm.user_id = (select auth.uid()) and tm.role = 'captain'
      )
    )
  );
create policy teams_manage_delete on public.teams for delete to authenticated
  using ((select private.can_manage(event_id)));

create policy team_members_select on public.team_members for select to authenticated
  using (
    (select private.is_team_member(team_id))
    or (select private.has_permission(event_id, 'people.view'))
  );
create policy team_members_manage_insert on public.team_members for insert to authenticated
  with check ((select private.can_manage(event_id)));
create policy team_members_manage_update on public.team_members for update to authenticated
  using ((select private.can_manage(event_id)))
  with check ((select private.can_manage(event_id)));
create policy team_members_manage_delete on public.team_members for delete to authenticated
  using ((select private.can_manage(event_id)));

create policy event_members_select on public.event_members for select to authenticated
  using (
    user_id = (select auth.uid())
    or (select private.has_permission(event_id, 'people.view'))
    or exists (
      select 1 from public.team_members mine
      join public.team_members theirs on theirs.team_id = mine.team_id
      where mine.user_id = (select auth.uid()) and theirs.user_id = event_members.user_id
        and mine.event_id = event_members.event_id
    )
  );

alter publication supabase_realtime add table public.team_members;

create function private.team_board_on(p_event uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((private.event_setting(p_event, 'teams') ->> 'board')::boolean, false)
    and exists (select 1 from public.events e where e.id = p_event and e.team_size_max > 1);
$$;

create function private.team_labels(p_labels text[])
returns text[]
language sql
immutable
set search_path = ''
as $$
  select coalesce(array_agg(q.l order by q.o), '{}') from (
    select left(lower(btrim(t.x)), 30) as l, min(t.o) as o
    from unnest(coalesce(p_labels, '{}')) with ordinality as t(x, o)
    where btrim(t.x) <> ''
    group by 1 order by min(t.o) limit 12) q;
$$;

create table public.team_seekers (
  event_id uuid not null,
  user_id uuid not null,
  skills text[] not null default '{}' check (cardinality(skills) <= 12),
  interests text[] not null default '{}' check (cardinality(interests) <= 12),
  timezone text check (length(timezone) <= 60),
  blurb text not null default '' check (length(blurb) <= 500),
  looking boolean not null default true,
  updated_at timestamptz not null default now(),
  primary key (event_id, user_id),
  foreign key (event_id, user_id) references public.event_members (event_id, user_id) on delete cascade
);
create index team_seekers_event_id_looking_idx on public.team_seekers (event_id) where looking;
alter table public.team_seekers enable row level security;
create policy team_seekers_select on public.team_seekers for select to authenticated
  using (user_id = (select auth.uid()) or (select private.can_manage(event_id)));

create table public.team_openings (
  event_id uuid not null,
  team_id uuid not null primary key,
  blurb text not null default '' check (length(blurb) <= 500),
  wanted text[] not null default '{}' check (cardinality(wanted) <= 12),
  open boolean not null default true,
  updated_at timestamptz not null default now(),
  foreign key (event_id, team_id) references public.teams (event_id, id) on delete cascade
);
create index team_openings_event_id_team_id_fk_idx on public.team_openings (event_id, team_id);
alter table public.team_openings enable row level security;
create policy team_openings_select on public.team_openings for select to authenticated
  using ((select private.event_role(event_id)) is not null);

create table public.team_requests (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null,
  team_id uuid not null,
  user_id uuid not null,
  direction text not null check (direction in ('request', 'invite')),
  message text not null default '' check (length(message) <= 500),
  status text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'withdrawn')),
  created_by uuid references public.profiles on delete set null,
  created_at timestamptz not null default now(),
  decided_at timestamptz,
  foreign key (event_id, team_id) references public.teams (event_id, id) on delete cascade,
  foreign key (event_id, user_id) references public.event_members (event_id, user_id) on delete cascade
);
create unique index team_requests_pending_idx on public.team_requests (team_id, user_id) where status = 'pending';
create index team_requests_event_id_team_id_fk_idx on public.team_requests (event_id, team_id);
create index team_requests_event_id_user_id_fk_idx on public.team_requests (event_id, user_id);
create index team_requests_created_by_fk_idx on public.team_requests (created_by);
alter table public.team_requests enable row level security;
create policy team_requests_select on public.team_requests for select to authenticated
  using ((select private.can_manage(event_id)) or user_id = (select auth.uid()) or (select private.is_team_member(team_id)));

create function private.assert_team_board(p_event uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.team_board_on(p_event) or not private.has_permission(p_event, 'event.compete') then
    raise exception 'only participants can use the team board' using errcode = '42501';
  end if;
end;
$$;

create function public.save_team_seeker(
  p_event uuid, p_skills text[], p_interests text[], p_timezone text, p_blurb text, p_looking boolean
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.assert_team_board(p_event);
  insert into public.team_seekers (event_id, user_id, skills, interests, timezone, blurb, looking)
  values (p_event, (select auth.uid()), private.team_labels(p_skills), private.team_labels(p_interests),
    nullif(btrim(p_timezone), ''), coalesce(btrim(p_blurb), ''), coalesce(p_looking, true))
  on conflict (event_id, user_id) do update set skills = excluded.skills, interests = excluded.interests,
    timezone = excluded.timezone, blurb = excluded.blurb, looking = excluded.looking, updated_at = now();
end;
$$;
revoke execute on function public.save_team_seeker(uuid, text[], text[], text, text, boolean) from public, anon;
grant execute on function public.save_team_seeker(uuid, text[], text[], text, text, boolean) to authenticated;

create function public.team_board_people(p_event uuid)
returns table (user_id uuid, display_name text, skills text[], interests text[], timezone text, blurb text, looking boolean, mine boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.team_board_on(p_event) or private.event_role(p_event) is null then
    raise exception 'the team board is off' using errcode = '42501';
  end if;
  return query
  select t.user_id, p.display_name, t.skills, t.interests, t.timezone, t.blurb, t.looking,
    t.user_id = (select auth.uid())
  from public.team_seekers t
  join public.profiles p on p.id = t.user_id
  join public.event_members m on m.event_id = t.event_id and m.user_id = t.user_id and m.role = 'participant' and m.status = 'active'
  where t.event_id = p_event
    and (t.user_id = (select auth.uid()) or (t.looking
      and not exists (select 1 from public.team_members tm where tm.event_id = p_event and tm.user_id = t.user_id)))
  order by t.updated_at desc;
end;
$$;
revoke execute on function public.team_board_people(uuid) from public, anon;
grant execute on function public.team_board_people(uuid) to authenticated;

create function public.save_team_opening(p_event uuid, p_blurb text, p_wanted text[], p_open boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_team uuid := private.my_team(p_event);
begin
  perform private.assert_team_board(p_event);
  if v_team is null then
    raise exception 'join or start a team first' using errcode = '22023';
  end if;
  insert into public.team_openings (event_id, team_id, blurb, wanted, open)
  values (p_event, v_team, coalesce(btrim(p_blurb), ''), private.team_labels(p_wanted), coalesce(p_open, true))
  on conflict (team_id) do update set blurb = excluded.blurb, wanted = excluded.wanted, open = excluded.open, updated_at = now();
end;
$$;
revoke execute on function public.save_team_opening(uuid, text, text[], boolean) from public, anon;
grant execute on function public.save_team_opening(uuid, text, text[], boolean) to authenticated;

create function public.team_board_openings(p_event uuid)
returns table (team_id uuid, team_name text, blurb text, wanted text[], open boolean, members integer, max_members integer, requested boolean, mine boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_max integer;
  v_mine uuid := private.my_team(p_event);
begin
  if not private.team_board_on(p_event) or private.event_role(p_event) is null then
    raise exception 'the team board is off' using errcode = '42501';
  end if;
  select e.team_size_max into v_max from public.events e where e.id = p_event;
  return query
  select o.team_id, t.name, o.blurb, o.wanted, o.open,
    (select count(*)::integer from public.team_members tm where tm.team_id = o.team_id), v_max::integer,
    exists (select 1 from public.team_requests r where r.team_id = o.team_id and r.user_id = (select auth.uid()) and r.status = 'pending'),
    o.team_id is not distinct from v_mine
  from public.team_openings o
  join public.teams t on t.id = o.team_id
  where o.event_id = p_event
    and (o.team_id is not distinct from v_mine or (o.open and t.locked_at is null
      and (select count(*) from public.team_members tm where tm.team_id = o.team_id) < v_max))
  order by o.updated_at desc;
end;
$$;
revoke execute on function public.team_board_openings(uuid) from public, anon;
grant execute on function public.team_board_openings(uuid) to authenticated;

create function public.request_to_join_team(p_event uuid, p_team uuid, p_message text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_me uuid := (select auth.uid());
begin
  perform private.assert_team_board(p_event);
  if private.my_team(p_event) is not null then
    raise exception 'leave your team first' using errcode = '22023';
  end if;
  if not exists (select 1 from public.team_openings where team_id = p_team and event_id = p_event and open) then
    raise exception 'that team isn''t looking' using errcode = '22023';
  end if;
  insert into public.team_requests (event_id, team_id, user_id, direction, message, created_by)
  values (p_event, p_team, v_me, 'request', left(coalesce(btrim(p_message), ''), 500), v_me)
  returning id into v_id;
  perform private.notify(
    array(select tm.user_id from public.team_members tm where tm.team_id = p_team and tm.role = 'captain'),
    p_event, 'team.request',
    coalesce((select display_name from public.profiles where id = v_me), 'Someone') || ' wants to join your team',
    left(coalesce(btrim(p_message), ''), 500),
    '/events/' || (select slug from public.events where id = p_event) || '/team');
  return v_id;
end;
$$;
revoke execute on function public.request_to_join_team(uuid, uuid, text) from public, anon;
grant execute on function public.request_to_join_team(uuid, uuid, text) to authenticated;

create function public.invite_to_team(p_event uuid, p_user uuid, p_message text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_team uuid := private.my_team(p_event);
  v_id uuid;
begin
  perform private.assert_team_board(p_event);
  if v_team is null then
    raise exception 'join or start a team first' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.team_seekers t where t.event_id = p_event and t.user_id = p_user and t.looking
      and not exists (select 1 from public.team_members tm where tm.event_id = p_event and tm.user_id = p_user)
  ) then
    raise exception 'that person isn''t looking for a team' using errcode = '22023';
  end if;
  insert into public.team_requests (event_id, team_id, user_id, direction, message, created_by)
  values (p_event, v_team, p_user, 'invite', left(coalesce(btrim(p_message), ''), 500), (select auth.uid()))
  returning id into v_id;
  perform private.notify(array[p_user], p_event, 'team.invited',
    (select t.name from public.teams t where t.id = v_team) || ' invited you to their team',
    left(coalesce(btrim(p_message), ''), 500),
    '/events/' || (select slug from public.events where id = p_event) || '/team');
  return v_id;
end;
$$;
revoke execute on function public.invite_to_team(uuid, uuid, text) from public, anon;
grant execute on function public.invite_to_team(uuid, uuid, text) to authenticated;

create function public.team_requests_inbox(p_event uuid)
returns table (id uuid, direction text, team_id uuid, team_name text, user_id uuid, user_name text, message text, status text, created_at timestamptz, decide boolean, sent boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_me uuid := (select auth.uid());
begin
  if not private.team_board_on(p_event) or private.event_role(p_event) is null then
    raise exception 'the team board is off' using errcode = '42501';
  end if;
  return query
  select r.id, r.direction, r.team_id, t.name, r.user_id, p.display_name, r.message, r.status, r.created_at,
    r.status = 'pending' and case r.direction
      when 'invite' then r.user_id = v_me
      else exists (select 1 from public.team_members tm where tm.team_id = r.team_id and tm.user_id = v_me and tm.role = 'captain')
    end,
    r.created_by = v_me
  from public.team_requests r
  join public.teams t on t.id = r.team_id
  join public.profiles p on p.id = r.user_id
  where r.event_id = p_event and (r.user_id = v_me or exists (select 1 from public.team_members tm where tm.team_id = r.team_id and tm.user_id = v_me))
  order by r.status = 'pending' desc, r.created_at desc
  limit 100;
end;
$$;
revoke execute on function public.team_requests_inbox(uuid) from public, anon;
grant execute on function public.team_requests_inbox(uuid) to authenticated;

create function public.answer_team_request(p_request uuid, p_accept boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req public.team_requests;
  v_me uuid := (select auth.uid());
  v_team public.teams;
begin
  select * into v_req from public.team_requests where id = p_request and status = 'pending';
  if v_req.id is null or not private.team_board_on(v_req.event_id) then
    raise exception 'that request is gone' using errcode = 'P0002';
  end if;
  if not (case v_req.direction
    when 'invite' then v_req.user_id = v_me
    else exists (select 1 from public.team_members tm where tm.team_id = v_req.team_id and tm.user_id = v_me and tm.role = 'captain')
  end) then
    raise exception 'that isn''t yours to answer' using errcode = '42501';
  end if;
  if p_accept then
    perform private.assert_can_change_teams(v_req.event_id);
    select * into v_team from public.teams where id = v_req.team_id;
    if v_team.locked_at is not null then
      raise exception 'this team is locked' using errcode = 'P0001';
    end if;
    if exists (select 1 from public.team_members tm where tm.event_id = v_req.event_id and tm.user_id = v_req.user_id) then
      raise exception 'they are already on a team' using errcode = 'P0001';
    end if;
    insert into public.team_members (event_id, team_id, user_id) values (v_req.event_id, v_req.team_id, v_req.user_id);
    update public.team_requests set status = 'withdrawn', decided_at = now()
    where event_id = v_req.event_id and user_id = v_req.user_id and status = 'pending' and id <> p_request;
    perform private.audit(v_req.event_id, 'team.request_accepted', 'team', v_req.team_id,
      jsonb_build_object('user', v_req.user_id, 'direction', v_req.direction));
  end if;
  update public.team_requests set status = case when p_accept then 'accepted' else 'declined' end, decided_at = now()
  where id = p_request;
  perform private.notify(array[v_req.created_by], v_req.event_id, 'team.answered',
    case when p_accept then
      case v_req.direction when 'invite' then 'Your invitation was accepted' else 'Your request to join was accepted' end
    else
      case v_req.direction when 'invite' then 'Your invitation was declined' else 'Your request to join was declined' end
    end,
    '', '/events/' || (select slug from public.events where id = v_req.event_id) || '/team');
end;
$$;
revoke execute on function public.answer_team_request(uuid, boolean) from public, anon;
grant execute on function public.answer_team_request(uuid, boolean) to authenticated;

create function public.withdraw_team_request(p_request uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.team_requests set status = 'withdrawn', decided_at = now()
  where id = p_request and status = 'pending' and created_by = (select auth.uid());
  if not found then
    raise exception 'that request is gone' using errcode = 'P0002';
  end if;
end;
$$;
revoke execute on function public.withdraw_team_request(uuid) from public, anon;
grant execute on function public.withdraw_team_request(uuid) to authenticated;

create function public.team_matching_overview(p_event uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_event public.events;
begin
  if not private.can_manage(p_event) then
    raise exception 'only organizers can match teams' using errcode = '42501';
  end if;
  select * into v_event from public.events where id = p_event;
  return jsonb_build_object(
    'min', v_event.team_size_min, 'max', v_event.team_size_max,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object('id', m.user_id, 'name', p.display_name,
        'skills', coalesce(t.skills, '{}'), 'interests', coalesce(t.interests, '{}'), 'timezone', t.timezone,
        'division', m.division_id) order by p.display_name)
      from public.event_members m
      join public.profiles p on p.id = m.user_id
      left join public.team_seekers t on t.event_id = m.event_id and t.user_id = m.user_id
      where m.event_id = p_event and m.role = 'participant' and m.status = 'active'
        and not exists (select 1 from public.team_members tm where tm.event_id = p_event and tm.user_id = m.user_id)), '[]'),
    'teams', coalesce((
      select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'locked', t.locked_at is not null,
        'division', t.division_id,
        'members', (select count(*) from public.team_members tm where tm.team_id = t.id),
        'skills', coalesce((select array_agg(distinct s) from public.team_members tm
           join public.team_seekers ts on ts.event_id = tm.event_id and ts.user_id = tm.user_id, unnest(ts.skills) s
           where tm.team_id = t.id), '{}')))
      from public.teams t where t.event_id = p_event), '[]'));
end;
$$;
revoke execute on function public.team_matching_overview(uuid) from public, anon;
grant execute on function public.team_matching_overview(uuid) to authenticated;

create function public.apply_team_matching(p_event uuid, p_groups jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_group jsonb;
  v_team uuid;
  v_user uuid;
  v_moved integer := 0;
begin
  if not private.can_manage(p_event) then
    raise exception 'only organizers can match teams' using errcode = '42501';
  end if;
  if jsonb_typeof(p_groups) <> 'array' or jsonb_array_length(p_groups) > 500 then
    raise exception 'send up to 500 groups' using errcode = '22023';
  end if;
  for v_group in select * from jsonb_array_elements(p_groups) loop
    v_team := nullif(v_group ->> 'team', '')::uuid;
    if v_team is null then
      insert into public.teams (event_id, name, created_by)
      values (p_event, left(btrim(v_group ->> 'name'), 60), (select auth.uid()))
      returning id into v_team;
    elsif not exists (select 1 from public.teams where id = v_team and event_id = p_event) then
      raise exception 'that team isn''t in this event' using errcode = '22023';
    end if;
    for v_user in select (jsonb_array_elements_text(v_group -> 'members'))::uuid loop
      perform public.set_team_membership(p_event, v_user, v_team);
      v_moved := v_moved + 1;
    end loop;
  end loop;
  perform private.audit(p_event, 'team.matched', 'event', p_event, jsonb_build_object('people', v_moved));
  return v_moved;
end;
$$;
revoke execute on function public.apply_team_matching(uuid, jsonb) from public, anon;
grant execute on function public.apply_team_matching(uuid, jsonb) to authenticated;

-- ─── supabase/schemas/07_communication.sql ─────────────────────────────────

create table public.announcements (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events on delete cascade,
  title text not null check (length(title) between 1 and 140),
  body_md text not null default '',
  severity public.announcement_severity not null default 'info',
  everyone boolean not null default true,
  publish_at timestamptz not null default now(),
  also_notify boolean not null default false,
  notified_at timestamptz,
  author_id uuid references public.profiles on delete set null,
  attachments jsonb not null default '[]'
    check (jsonb_typeof(attachments) = 'array' and jsonb_array_length(attachments) <= 10),
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, id)
);
create index announcements_event_idx on public.announcements (event_id, publish_at desc);

create trigger announcements_touch before update on public.announcements
  for each row execute function private.touch_updated_at();

create function private.broadcast_announcements(p_event uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform realtime.send('{}'::jsonb, 'changed', 'announcements:' || p_event::text, false);
exception when others then
  null;
end;
$$;

create function private.announcements_changed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.broadcast_announcements(coalesce(new.event_id, old.event_id));
  return null;
end;
$$;

create trigger announcements_broadcast after insert or update or delete on public.announcements
  for each row execute function private.announcements_changed();

create table public.announcement_audiences (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null,
  announcement_id uuid not null,
  role public.event_role,
  division_id uuid,
  team_id uuid,
  check (num_nonnulls(role, division_id, team_id) = 1),
  unique nulls not distinct (announcement_id, role, division_id, team_id),
  foreign key (event_id, announcement_id) references public.announcements (event_id, id) on delete cascade,
  foreign key (event_id, division_id) references public.divisions (event_id, id) on delete cascade,
  foreign key (event_id, team_id) references public.teams (event_id, id) on delete cascade
);

create function private.in_announcement_audience(p_announcement uuid, p_event uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.announcement_audiences a
    where a.announcement_id = p_announcement
      and (
        a.role = private.event_role(p_event)
        or a.team_id = private.my_team(p_event)
        or a.division_id in (
          select m.division_id from public.event_members m
          where m.event_id = p_event and m.user_id = (select auth.uid()) and m.status = 'active'
          union
          select t.division_id from public.teams t where t.id = private.my_team(p_event)
        )
      )
  );
$$;
grant execute on function private.in_announcement_audience(uuid, uuid) to authenticated;

create function private.deliver_announcement(p_announcement uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_a public.announcements;
  v_slug text;
  v_users uuid[];
begin
  update public.announcements set notified_at = now()
  where id = p_announcement and also_notify and notified_at is null and deleted_at is null
    and publish_at <= now()
  returning * into v_a;
  if v_a.id is null then
    return 0;
  end if;
  select slug into v_slug from public.events where id = v_a.event_id;
  select array_agg(m.user_id) into v_users
  from public.event_members m
  where m.event_id = v_a.event_id and m.status = 'active'
    and (v_a.everyone
      or exists (select 1 from public.announcement_audiences x
        where x.announcement_id = v_a.id and x.role = m.role)
      or exists (select 1 from public.announcement_audiences x
        where x.announcement_id = v_a.id and x.division_id = m.division_id)
      or exists (select 1 from public.announcement_audiences x
        join public.team_members tm on tm.team_id = x.team_id
        where x.announcement_id = v_a.id and tm.user_id = m.user_id));
  return private.notify(coalesce(v_users, '{}'), v_a.event_id, 'announcement', v_a.title,
    left(v_a.body_md, 2000), '/events/' || v_slug || '/messages', '{}', true);
end;
$$;
revoke execute on function private.deliver_announcement(uuid) from anon, authenticated;

create function private.deliver_due_announcements()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_count integer := 0;
begin
  for v_id in
    select id from public.announcements
    where also_notify and notified_at is null and deleted_at is null and publish_at <= now()
  loop
    v_count := v_count + private.deliver_announcement(v_id);
  end loop;
  return v_count;
end;
$$;
revoke execute on function private.deliver_due_announcements() from anon, authenticated;

-- Organizers, and judges when `announcements.judges` is on.
create function private.may_announce(p_event uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.can_manage(p_event)
    or (
      private.event_role(p_event) = 'judge'
      and coalesce((private.event_setting(p_event, 'announcements') ->> 'judges')::boolean, false)
    );
$$;
grant execute on function private.may_announce(uuid) to authenticated;

create function public.post_announcement(
  p_event uuid,
  p_title text,
  p_body text,
  p_severity public.announcement_severity,
  p_publish_at timestamptz default null,
  p_roles public.event_role[] default '{}',
  p_divisions uuid[] default '{}',
  p_teams uuid[] default '{}',
  p_anonymous boolean default false,
  p_notify boolean default false,
  p_id uuid default null,
  p_attachments jsonb default '[]'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_everyone boolean := coalesce(cardinality(p_roles), 0) + coalesce(cardinality(p_divisions), 0)
    + coalesce(cardinality(p_teams), 0) = 0;
begin
  if not private.may_announce(p_event) then
    raise exception 'Only organizers can post announcements.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_attachments) <> 'array' or exists (
    select 1 from jsonb_array_elements(p_attachments) a
    where jsonb_typeof(a) <> 'object'
      or coalesce(a ->> 'path', '') not like p_event::text || '/' || v_id::text || '/%'
      or length(coalesce(a ->> 'name', '')) not between 1 and 255
  ) then
    raise exception 'attachments must be uploaded to this announcement' using errcode = '22023';
  end if;
  if not private.can_manage(p_event) then
    if cardinality(p_teams) > 0 and private.hides_team_names(p_event) then
      raise exception 'Judging is blind, so judges can''t address teams.' using errcode = '42501';
    end if;
    -- A judge's announcement always carries their name.
    p_anonymous := false;
  end if;
  insert into public.announcements (id, event_id, title, body_md, severity, everyone, publish_at, also_notify, author_id, attachments)
  values (v_id, p_event, trim(p_title), coalesce(p_body, ''), p_severity, v_everyone,
    coalesce(p_publish_at, now()), p_notify, case when p_anonymous then null else (select auth.uid()) end,
    p_attachments);
  insert into public.announcement_audiences (event_id, announcement_id, role)
  select distinct p_event, v_id, r from unnest(p_roles) r;
  insert into public.announcement_audiences (event_id, announcement_id, division_id)
  select distinct p_event, v_id, d from unnest(p_divisions) d;
  insert into public.announcement_audiences (event_id, announcement_id, team_id)
  select distinct p_event, v_id, t from unnest(p_teams) t;
  perform private.audit(p_event, 'announcement.posted', 'announcement', v_id,
    jsonb_build_object('title', trim(p_title), 'everyone', v_everyone,
      'scheduled', p_publish_at is not null and p_publish_at > now(), 'anonymous', p_anonymous,
      'notify', p_notify));
  if p_notify and coalesce(p_publish_at, now()) <= now() then
    perform private.deliver_announcement(v_id);
  end if;
  return v_id;
end;
$$;
grant execute on function public.post_announcement(uuid, text, text, public.announcement_severity, timestamptz, public.event_role[], uuid[], uuid[], boolean, boolean, uuid, jsonb) to authenticated;

create table public.announcement_reads (
  announcement_id uuid not null references public.announcements on delete cascade,
  user_id uuid not null references public.profiles on delete cascade,
  read_at timestamptz not null default now(),
  primary key (announcement_id, user_id)
);
create index announcement_reads_user_idx on public.announcement_reads (user_id);

create function private.audit_announcement_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.deleted_at is not null and old.deleted_at is null then
    perform private.audit(new.event_id, 'announcement.deleted', 'announcement', new.id,
      jsonb_build_object('title', new.title));
  end if;
  return new;
end;
$$;

create trigger announcements_audit_delete after update of deleted_at on public.announcements
  for each row execute function private.audit_announcement_delete();

create table public.clarifications (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events on delete cascade,
  team_id uuid,
  asked_by uuid references public.profiles on delete set null,
  topic text not null default 'general' check (topic ~ '^(general|[a-z][a-z0-9-]*\.[a-z0-9-]+(:[0-9a-f-]+)?)$'),
  subject text not null check (length(subject) between 1 and 140),
  audience text not null default 'organizers' check (audience in ('organizers', 'judges', 'staff')),
  status public.clarification_status not null default 'open',
  visibility public.clarification_visibility not null default 'private',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, id),
  foreign key (event_id, team_id) references public.teams (event_id, id) on delete set null (team_id)
);
create index clarifications_event_idx on public.clarifications (event_id, created_at desc);
create index clarifications_team_idx on public.clarifications (team_id) where team_id is not null;

create trigger clarifications_touch before update on public.clarifications
  for each row execute function private.touch_updated_at();

create table public.clarification_messages (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null,
  clarification_id uuid not null,
  author_id uuid references public.profiles on delete set null,
  author_role text not null default 'participant' check (author_role in ('participant', 'organizer', 'judge')),
  body_md text not null default '' check (length(body_md) <= 10000),
  attachments jsonb not null default '[]'
    check (jsonb_typeof(attachments) = 'array' and jsonb_array_length(attachments) <= 10),
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  check (length(body_md) > 0 or jsonb_array_length(attachments) > 0),
  foreign key (event_id, clarification_id) references public.clarifications (event_id, id) on delete cascade
);
create index clarification_messages_thread_idx on public.clarification_messages (clarification_id, created_at);

create function private.chat_allows(p_event uuid, p_key text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((private.event_setting(p_event, 'chat') ->> p_key)::boolean, false);
$$;

create function private.prepare_clarification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.asked_by := coalesce((select auth.uid()), new.asked_by);
  if (select auth.uid()) is not null and not private.can_manage(new.event_id) then
    if new.team_id is not null and private.event_role(new.event_id) = 'judge' then
      -- A judge messaging a team: only in a judges conversation, never under blind judging.
      if new.audience <> 'judges' or private.hides_team_names(new.event_id) then
        raise exception 'You can''t message that team.' using errcode = '42501';
      end if;
    else
      new.team_id := case
        when new.audience <> 'staff' and private.chat_allows(new.event_id, 'copyTeam')
          then private.my_team(new.event_id)
      end;
    end if;
    new.status := 'open';
    new.visibility := 'private';
  end if;
  return new;
end;
$$;

create trigger clarifications_prepare before insert on public.clarifications
  for each row execute function private.prepare_clarification();

create function private.prepare_clarification_message()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_manager boolean := private.can_manage(new.event_id)
    or private.has_permission(new.event_id, 'clarifications.answer');
  v_asker uuid := (select asked_by from public.clarifications where id = new.clarification_id);
begin
  if exists (
    select 1 from jsonb_array_elements(new.attachments) a
    where jsonb_typeof(a) <> 'object'
      or coalesce(a ->> 'path', '') not like new.event_id::text || '/' || new.clarification_id::text || '/%'
      or length(coalesce(a ->> 'name', '')) not between 1 and 255
  ) then
    raise exception 'attachments must be uploaded to this conversation' using errcode = '22023';
  end if;
  new.author_id := coalesce((select auth.uid()), new.author_id);
  new.author_role := case
    when v_manager then 'organizer'
    when private.event_role(new.event_id) = 'judge' then 'judge'
    else 'participant'
  end;
  update public.clarifications
  set status = case when new.author_id = v_asker then 'open' else 'answered' end::public.clarification_status
  where id = new.clarification_id and status <> 'closed';
  return new;
end;
$$;

create trigger clarification_messages_prepare before insert on public.clarification_messages
  for each row execute function private.prepare_clarification_message();

create function public.ask_clarification(
  p_event uuid, p_subject text, p_body text, p_topic text default 'general',
  p_audience text default 'organizers'
)
returns public.clarifications
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := gen_random_uuid();
  v_row public.clarifications;
begin
  perform private.require_network(p_event);
  insert into public.clarifications (id, event_id, subject, topic, audience)
  values (v_id, p_event, trim(p_subject), p_topic, p_audience);
  insert into public.clarification_messages (event_id, clarification_id, body_md)
  values (p_event, v_id, p_body);
  select * into v_row from public.clarifications where id = v_id;
  return v_row;
end;
$$;
grant execute on function public.ask_clarification(uuid, text, text, text, text) to authenticated;

-- An organizer or judge starts a conversation with one team. Organizers write
-- as organizers; judges in a judges conversation, which needs `chat.judges`.
create function public.message_team(p_event uuid, p_team uuid, p_subject text, p_body text)
returns public.clarifications
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := gen_random_uuid();
  v_row public.clarifications;
begin
  perform private.require_network(p_event);
  insert into public.clarifications (id, event_id, team_id, subject, audience)
  values (v_id, p_event, p_team, trim(p_subject),
    case when private.can_manage(p_event) then 'organizers' else 'judges' end);
  insert into public.clarification_messages (event_id, clarification_id, body_md)
  values (p_event, v_id, p_body);
  select * into v_row from public.clarifications where id = v_id;
  return v_row;
end;
$$;
grant execute on function public.message_team(uuid, uuid, text, text) to authenticated;

create function private.can_see_clarification(p_clarification uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.clarifications c
    where c.id = p_clarification
      and (
        private.can_manage(c.event_id)
        or private.has_permission(c.event_id, 'clarifications.answer')
        or c.asked_by = (select auth.uid())
        or (c.team_id is not null and private.is_team_member(c.team_id))
        or (c.audience <> 'organizers' and private.event_role(c.event_id) = 'judge')
        or (
          c.audience = 'organizers' and c.visibility = 'public'
          and private.has_permission(c.event_id, 'event.view')
        )
      )
  );
$$;
grant execute on function private.can_see_clarification(uuid) to authenticated;
grant execute on function private.chat_allows(uuid, text) to authenticated;

create function private.can_write_clarification(p_clarification uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.clarifications c
    where c.id = p_clarification
      and private.chat_allows(c.event_id, 'enabled')
      and private.network_allowed(c.event_id)
      and (
        ((private.can_manage(c.event_id) or private.has_permission(c.event_id, 'clarifications.answer'))
          and (c.audience <> 'staff' or private.chat_allows(c.event_id, 'staff')))
        or (
          c.status <> 'closed'
          and (
            (c.audience = 'staff' and private.event_role(c.event_id) = 'judge' and private.chat_allows(c.event_id, 'staff'))
            or (c.audience = 'judges' and private.event_role(c.event_id) = 'judge' and private.chat_allows(c.event_id, 'judges'))
            or (
              c.audience <> 'staff'
              and private.chat_allows(c.event_id, 'participants')
              and (c.audience = 'organizers' or private.chat_allows(c.event_id, 'judges'))
              and (c.asked_by = (select auth.uid()) or (c.team_id is not null and private.is_team_member(c.team_id)))
            )
          )
        )
      )
  );
$$;
grant execute on function private.can_write_clarification(uuid) to authenticated;

create table public.clarification_archives (
  clarification_id uuid not null references public.clarifications on delete cascade,
  user_id uuid not null references public.profiles on delete cascade,
  archived_at timestamptz not null default now(),
  primary key (clarification_id, user_id)
);
create index clarification_archives_user_idx on public.clarification_archives (user_id);

create index clarification_messages_event_id_clarification_id_fk_idx on public.clarification_messages (event_id, clarification_id);
create index clarifications_event_id_team_id_fk_idx on public.clarifications (event_id, team_id);
create index announcements_author_id_fk_idx on public.announcements (author_id);
create index announcement_audiences_event_id_announcement_id_fk_idx on public.announcement_audiences (event_id, announcement_id);
create index announcement_audiences_event_id_division_id_fk_idx on public.announcement_audiences (event_id, division_id);
create index announcement_audiences_event_id_team_id_fk_idx on public.announcement_audiences (event_id, team_id);
create index clarification_messages_author_id_fk_idx on public.clarification_messages (author_id);
create index clarifications_asked_by_fk_idx on public.clarifications (asked_by);

alter table public.announcements enable row level security;
alter table public.announcement_audiences enable row level security;
alter table public.announcement_reads enable row level security;
alter table public.clarifications enable row level security;
alter table public.clarification_messages enable row level security;
alter table public.clarification_archives enable row level security;

create policy announcements_select on public.announcements for select to authenticated
  using (
    (select private.can_manage(event_id))
    or (
      deleted_at is null
      and publish_at <= now()
      and (select private.has_permission(event_id, 'event.view'))
      and (everyone or private.in_announcement_audience(id, event_id))
    )
  );
create policy announcements_write_update on public.announcements for update to authenticated
  using ((select private.can_manage(event_id)))
  with check ((select private.can_manage(event_id)));
create policy announcements_write_delete on public.announcements for delete to authenticated
  using ((select private.can_manage(event_id)));

create policy announcement_audiences_select on public.announcement_audiences for select to authenticated
  using ((select private.can_manage(event_id)));

create policy announcement_reads_own on public.announcement_reads for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy clarifications_select on public.clarifications for select to authenticated
  using ((select private.can_see_clarification(id)));
create policy clarifications_insert on public.clarifications for insert to authenticated
  with check (
    (select private.chat_allows(event_id, 'enabled'))
    and (
      (
        audience = 'staff'
        and (select private.chat_allows(event_id, 'staff'))
        and ((select private.can_manage(event_id)) or (select private.event_role(event_id)) = 'judge')
      )
      or (audience <> 'staff' and (select private.can_manage(event_id)))
      or (
        audience = 'judges'
        and team_id is not null
        and (select private.event_role(event_id)) = 'judge'
        and (select private.chat_allows(event_id, 'judges'))
      )
      or (
        (select private.has_permission(event_id, 'event.compete'))
        and (select private.chat_allows(event_id, 'participants'))
        and (audience = 'organizers' or (audience = 'judges' and (select private.chat_allows(event_id, 'judges'))))
      )
    )
  );
create policy clarifications_manage on public.clarifications for update to authenticated
  using ((select private.can_manage(event_id)) or (select private.has_permission(event_id, 'clarifications.answer')));

create policy clarification_messages_select on public.clarification_messages for select to authenticated
  using ((select private.can_see_clarification(clarification_id)) and (deleted_at is null or (select private.can_manage(event_id))));
create policy clarification_messages_insert on public.clarification_messages for insert to authenticated
  with check ((select private.can_write_clarification(clarification_id)));
create policy clarification_messages_moderate on public.clarification_messages for update to authenticated
  using ((select private.can_manage(event_id)));

create policy clarification_archives_own on public.clarification_archives for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()) and (select private.can_see_clarification(clarification_id)));

alter publication supabase_realtime add table
  public.announcements, public.clarifications, public.clarification_messages, public.event_windows;

-- ─── supabase/schemas/08_sessions.sql ──────────────────────────────────────

create type public.slot_kind as enum ('everyone', 'choose');
create type public.session_visibility as enum ('everyone', 'staff');
create type public.attendance_method as enum ('roster', 'code');

create table public.session_slots (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events on delete cascade,
  name text check (name is null or length(name) between 1 and 80),
  kind public.slot_kind not null default 'everyone',
  starts_at timestamptz not null,
  ends_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, id),
  check (ends_at is null or ends_at > starts_at)
);
create index session_slots_event_idx on public.session_slots (event_id, starts_at);

create trigger session_slots_touch before update on public.session_slots
  for each row execute function private.touch_updated_at();

create table public.session_categories (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events on delete cascade,
  kind text not null default 'session'
    check (kind ~ '^[a-z][a-z0-9_-]{0,39}(\.[a-z][a-z0-9_-]{0,39})?$'),
  label text not null check (length(label) between 1 and 40),
  sort smallint not null default 0,
  unique (event_id, kind, label),
  unique (event_id, id)
);

create table public.event_sessions (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null,
  slot_id uuid not null,
  category_id uuid,
  kind text not null default 'session'
    check (kind ~ '^[a-z][a-z0-9_-]{0,39}(\.[a-z][a-z0-9_-]{0,39})?$'),
  name text not null check (length(name) between 1 and 120),
  description_md text not null default '' check (length(description_md) <= 20000),
  location text check (length(location) <= 200),
  starts_at timestamptz,
  ends_at timestamptz,
  host_note text check (length(host_note) <= 200),
  capacity integer check (capacity > 0),
  required boolean not null default false,
  takes_attendance boolean not null default false,
  visibility public.session_visibility not null default 'everyone',
  sort smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, id),
  unique (slot_id, id),
  check (ends_at is null or starts_at is null or ends_at > starts_at),
  foreign key (event_id, slot_id) references public.session_slots (event_id, id) on delete cascade,
  foreign key (event_id, category_id) references public.session_categories (event_id, id)
    on delete set null (category_id)
);
create index event_sessions_event_idx on public.event_sessions (event_id);

create trigger event_sessions_touch before update on public.event_sessions
  for each row execute function private.touch_updated_at();

create table public.session_hosts (
  event_id uuid not null,
  session_id uuid not null,
  user_id uuid not null,
  primary key (session_id, user_id),
  foreign key (event_id, session_id) references public.event_sessions (event_id, id) on delete cascade,
  foreign key (event_id, user_id) references public.event_members on delete cascade
);

create table public.session_signups (
  event_id uuid not null,
  slot_id uuid not null,
  session_id uuid not null,
  user_id uuid not null,
  created_at timestamptz not null default now(),
  primary key (slot_id, user_id),
  foreign key (slot_id, session_id) references public.event_sessions (slot_id, id)
    on delete cascade on update cascade,
  foreign key (event_id, slot_id) references public.session_slots (event_id, id) on delete cascade,
  foreign key (event_id, user_id) references public.event_members on delete cascade
);
create index session_signups_session_idx on public.session_signups (session_id);

create table public.session_attendance (
  event_id uuid not null,
  session_id uuid not null,
  user_id uuid not null,
  method public.attendance_method not null,
  marked_by uuid references public.profiles on delete set null,
  created_at timestamptz not null default now(),
  primary key (session_id, user_id),
  foreign key (event_id, session_id) references public.event_sessions (event_id, id) on delete cascade,
  foreign key (event_id, user_id) references public.event_members on delete cascade
);

create table public.session_codes (
  event_id uuid not null,
  session_id uuid primary key,
  code text not null check (code ~ '^[A-Z2-9]{6}$'),
  created_at timestamptz not null default now(),
  unique (event_id, code),
  foreign key (event_id, session_id) references public.event_sessions (event_id, id) on delete cascade
);

create function private.hosts_session(p_session uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.session_hosts
    where session_id = p_session and user_id = (select auth.uid())
  );
$$;

create function private.takes_attendance(p_event uuid, p_session uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.has_permission(p_event, 'sessions.attendance') or private.hosts_session(p_session);
$$;

create function private.can_see_session(p_event uuid, p_session uuid, p_visibility public.session_visibility)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.section_open(p_event, 'agenda')
    and (p_visibility = 'everyone' or private.takes_attendance(p_event, p_session));
$$;

create function private.check_session_capacity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_capacity integer;
begin
  if tg_op = 'UPDATE' and new.session_id = old.session_id then
    return new;
  end if;
  select capacity into v_capacity from public.event_sessions where id = new.session_id for update;
  if v_capacity is not null
     and (select count(*) from public.session_signups where session_id = new.session_id) >= v_capacity then
    raise exception 'this session is full' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger session_signups_capacity before insert or update of session_id on public.session_signups
  for each row execute function private.check_session_capacity();

create function private.apply_session_picks(p_event uuid, p_user uuid, p_sessions uuid[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_session record;
begin
  for v_session in
    select s.id, s.slot_id from public.event_sessions s
    join public.session_slots sl on sl.id = s.slot_id
    where s.event_id = p_event and s.id = any(p_sessions) and sl.kind = 'choose'
  loop
    begin
      insert into public.session_signups (event_id, slot_id, session_id, user_id)
      values (p_event, v_session.slot_id, v_session.id, p_user)
      on conflict (slot_id, user_id) do nothing;
    exception when check_violation then
      perform private.audit(p_event, 'session.pick_skipped', 'session', v_session.id,
        jsonb_build_object('user', p_user, 'reason', sqlerrm));
    end;
  end loop;
end;
$$;

create function public.event_agenda(p_event uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_member boolean := private.has_permission(p_event, 'event.view');
begin
  if not private.can_view_event(p_event) then
    raise exception 'event not found' using errcode = 'P0002';
  end if;
  if not private.section_open(p_event, 'agenda') then
    return jsonb_build_object('signups_open', false, 'categories', '[]'::jsonb, 'slots', '[]'::jsonb);
  end if;
  return jsonb_build_object(
    'signups_open', private.window_open(p_event, 'sessions'),
    'categories', coalesce((
      select jsonb_agg(jsonb_build_object('kind', c.kind, 'label', c.label) order by c.kind, c.sort, c.label)
      from public.session_categories c where c.event_id = p_event
    ), '[]'),
    'slots', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', sl.id, 'name', sl.name, 'kind', sl.kind,
        'starts_at', sl.starts_at, 'ends_at', sl.ends_at,
        'sessions', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', s.id, 'kind', s.kind, 'name', s.name, 'description_md', s.description_md,
            'location', s.location, 'starts_at', s.starts_at, 'ends_at', s.ends_at,
            'host_note', s.host_note, 'capacity', s.capacity, 'required', s.required,
            'takes_attendance', s.takes_attendance, 'visibility', s.visibility,
            'category', (select c.label from public.session_categories c where c.id = s.category_id),
            'hosts', coalesce((
              select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name) order by p.display_name)
              from public.session_hosts h join public.profiles p on p.id = h.user_id
              where h.session_id = s.id and v_member
            ), '[]'),
            'taken', (select count(*) from public.session_signups g where g.session_id = s.id),
            'mine', exists (
              select 1 from public.session_signups g where g.session_id = s.id and g.user_id = v_uid
            ),
            'attended', exists (
              select 1 from public.session_attendance a where a.session_id = s.id and a.user_id = v_uid
            ),
            'can_take_attendance', s.takes_attendance and private.takes_attendance(p_event, s.id)
          ) order by coalesce(s.starts_at, sl.starts_at), s.sort, s.name)
          from public.event_sessions s
          where s.slot_id = sl.id and private.can_see_session(p_event, s.id, s.visibility)
        ), '[]')
      ) order by sl.starts_at, sl.name)
      from public.session_slots sl where sl.event_id = p_event
    ), '[]')
  );
end;
$$;

create function public.save_agenda(p_event uuid, p_agenda jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.can_manage(p_event) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return private.write_agenda(p_event, p_agenda);
end;
$$;

create function private.write_agenda(p_event uuid, p_agenda jsonb)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_removed integer;
  v_slot jsonb;
  v_slot_id uuid;
  v_session jsonb;
  v_session_id uuid;
  v_keep_slots uuid[] := '{}';
  v_keep_sessions uuid[] := '{}';
  v_kind text;
begin
  for v_kind in
    select distinct sess ->> 'kind'
    from jsonb_array_elements(coalesce(p_agenda -> 'slots', '[]')) sl,
      jsonb_array_elements(coalesce(sl -> 'sessions', '[]')) sess
    where (sess ->> 'kind') like '%.%'
  loop
    if not private.plugin_enabled(p_event, split_part(v_kind, '.', 1))
      and not exists (select 1 from public.event_sessions where event_id = p_event and kind = v_kind) then
      raise exception 'turn on the % extension to use its session types', split_part(v_kind, '.', 1)
        using errcode = '22023';
    end if;
  end loop;

  delete from public.session_categories c
  where c.event_id = p_event
    and not exists (
      select 1 from jsonb_array_elements(coalesce(p_agenda -> 'categories', '[]')) as l
      where l ->> 'kind' = c.kind and l ->> 'label' = c.label
    );
  insert into public.session_categories (event_id, kind, label, sort)
  select p_event, l.value ->> 'kind', l.value ->> 'label', (l.ordinality - 1)::smallint
  from jsonb_array_elements(coalesce(p_agenda -> 'categories', '[]')) with ordinality as l(value, ordinality)
  on conflict (event_id, kind, label) do update set sort = excluded.sort;

  for v_slot in select * from jsonb_array_elements(coalesce(p_agenda -> 'slots', '[]')) loop
    v_slot_id := coalesce((v_slot ->> 'id')::uuid, gen_random_uuid());
    insert into public.session_slots (id, event_id, name, kind, starts_at, ends_at)
    values (v_slot_id, p_event, nullif(v_slot ->> 'name', ''), (v_slot ->> 'kind')::public.slot_kind,
      (v_slot ->> 'starts_at')::timestamptz, (v_slot ->> 'ends_at')::timestamptz)
    on conflict (id) do update set
      name = excluded.name, kind = excluded.kind, starts_at = excluded.starts_at, ends_at = excluded.ends_at
    where public.session_slots.event_id = p_event;
    v_keep_slots := v_keep_slots || v_slot_id;

    for v_session in
      select value from jsonb_array_elements(coalesce(v_slot -> 'sessions', '[]')) with ordinality
      order by ordinality
    loop
      v_session_id := coalesce((v_session ->> 'id')::uuid, gen_random_uuid());
      insert into public.event_sessions (id, event_id, slot_id, category_id, kind, name, description_md,
        location, starts_at, ends_at, host_note, capacity, required, takes_attendance, visibility, sort)
      values (v_session_id, p_event, v_slot_id,
        (select c.id from public.session_categories c
          where c.event_id = p_event and c.kind = coalesce(v_session ->> 'kind', 'session')
            and c.label = v_session ->> 'category'),
        coalesce(v_session ->> 'kind', 'session'), v_session ->> 'name',
        coalesce(v_session ->> 'description_md', ''), nullif(v_session ->> 'location', ''),
        (v_session ->> 'starts_at')::timestamptz, (v_session ->> 'ends_at')::timestamptz,
        nullif(v_session ->> 'host_note', ''), (v_session ->> 'capacity')::integer,
        coalesce((v_session ->> 'required')::boolean, false),
        coalesce((v_session ->> 'takes_attendance')::boolean, false),
        coalesce(v_session ->> 'visibility', 'everyone')::public.session_visibility,
        cardinality(v_keep_sessions)::smallint)
      on conflict (id) do update set
        slot_id = excluded.slot_id, category_id = excluded.category_id, kind = excluded.kind,
        name = excluded.name, description_md = excluded.description_md, location = excluded.location,
        starts_at = excluded.starts_at, ends_at = excluded.ends_at, host_note = excluded.host_note,
        capacity = excluded.capacity, required = excluded.required,
        takes_attendance = excluded.takes_attendance, visibility = excluded.visibility, sort = excluded.sort
      where public.event_sessions.event_id = p_event;
      v_keep_sessions := v_keep_sessions || v_session_id;

      delete from public.session_hosts
      where session_id = v_session_id
        and user_id not in (
          select (value #>> '{}')::uuid from jsonb_array_elements(coalesce(v_session -> 'hosts', '[]'))
        );
      insert into public.session_hosts (event_id, session_id, user_id)
      select p_event, v_session_id, (value #>> '{}')::uuid
      from jsonb_array_elements(coalesce(v_session -> 'hosts', '[]'))
      on conflict do nothing;
    end loop;
  end loop;

  delete from public.event_sessions where event_id = p_event and id <> all (v_keep_sessions);
  get diagnostics v_removed = row_count;
  delete from public.session_slots where event_id = p_event and id <> all (v_keep_slots);
  delete from public.session_signups g using public.session_slots sl
  where g.slot_id = sl.id and sl.event_id = p_event and sl.kind = 'everyone';

  perform private.audit(p_event, 'sessions.agenda_saved', 'event', p_event, jsonb_build_object(
    'slots', cardinality(v_keep_slots), 'sessions', cardinality(v_keep_sessions), 'removed', v_removed));
  return v_removed;
end;
$$;

create function public.choose_session(p_session uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_session public.event_sessions;
  v_kind public.slot_kind;
begin
  select * into v_session from public.event_sessions where id = p_session;
  if v_session.id is null
     or not private.has_permission(v_session.event_id, 'event.view')
     or not private.can_see_session(v_session.event_id, v_session.id, v_session.visibility) then
    raise exception 'session not found' using errcode = 'P0002';
  end if;
  perform private.require_network(v_session.event_id);
  select kind into v_kind from public.session_slots where id = v_session.slot_id;
  if v_kind <> 'choose' then
    raise exception 'everyone attends this one; there''s nothing to pick' using errcode = '22023';
  end if;
  if not private.window_open(v_session.event_id, 'sessions') then
    raise exception 'session sign-ups are closed' using errcode = '42501';
  end if;

  insert into public.session_signups (event_id, slot_id, session_id, user_id)
  values (v_session.event_id, v_session.slot_id, v_session.id, v_uid)
  on conflict (slot_id, user_id) do update set session_id = excluded.session_id, created_at = now();
  perform private.audit(v_session.event_id, 'session.signed_up', 'session', v_session.id, '{}');
end;
$$;

create function public.leave_session_slot(p_slot uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event uuid;
  v_session uuid;
begin
  select event_id, session_id into v_event, v_session
  from public.session_signups where slot_id = p_slot and user_id = (select auth.uid());
  if v_event is null then
    return;
  end if;
  perform private.require_network(v_event);
  if not private.window_open(v_event, 'sessions') then
    raise exception 'session sign-ups are closed' using errcode = '42501';
  end if;
  delete from public.session_signups where slot_id = p_slot and user_id = (select auth.uid());
  perform private.audit(v_event, 'session.left', 'session', v_session, '{}');
end;
$$;

create function public.session_roster(p_session uuid)
returns table (user_id uuid, display_name text, signed_up boolean, attended_at timestamptz,
  method public.attendance_method)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_event uuid;
  v_kind public.slot_kind;
begin
  select s.event_id, sl.kind into v_event, v_kind
  from public.event_sessions s join public.session_slots sl on sl.id = s.slot_id
  where s.id = p_session;
  if v_event is null or not private.takes_attendance(v_event, p_session) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
  with expected as (
    select g.user_id, true as signed_up from public.session_signups g where g.session_id = p_session
    union
    select m.user_id, false from public.event_members m
    where v_kind = 'everyone' and m.event_id = v_event and m.role = 'participant' and m.status = 'active'
    union
    select a.user_id, false from public.session_attendance a where a.session_id = p_session
  )
  select e.user_id, p.display_name, bool_or(e.signed_up), a.created_at, a.method
  from expected e
  join public.profiles p on p.id = e.user_id
  left join public.session_attendance a on a.session_id = p_session and a.user_id = e.user_id
  group by e.user_id, p.display_name, a.created_at, a.method
  order by p.display_name;
end;
$$;

create function public.set_attendance(p_session uuid, p_user uuid, p_attended boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event uuid;
begin
  select event_id into v_event from public.event_sessions where id = p_session;
  if v_event is null or not private.takes_attendance(v_event, p_session) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_attended then
    insert into public.session_attendance (event_id, session_id, user_id, method, marked_by)
    values (v_event, p_session, p_user, 'roster', (select auth.uid()))
    on conflict do nothing;
  else
    delete from public.session_attendance where session_id = p_session and user_id = p_user;
  end if;
  perform private.audit(v_event, 'session.attendance_marked', 'session', p_session,
    jsonb_build_object('user', p_user, 'attended', p_attended));
end;
$$;

create function public.session_code(p_session uuid, p_rotate boolean default false)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event uuid;
  v_code text;
begin
  select event_id into v_event from public.event_sessions where id = p_session and takes_attendance;
  if v_event is null or not private.takes_attendance(v_event, p_session) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not p_rotate then
    select code into v_code from public.session_codes where session_id = p_session;
    if v_code is not null then
      return v_code;
    end if;
  end if;
  loop
    select string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + floor(random() * 31)::integer, 1), '')
    into v_code from generate_series(1, 6);
    begin
      insert into public.session_codes (event_id, session_id, code) values (v_event, p_session, v_code)
      on conflict (session_id) do update set code = excluded.code, created_at = now();
      exit;
    exception when unique_violation then
    end;
  end loop;
  if p_rotate then
    perform private.audit(v_event, 'session.code_rotated', 'session', p_session, '{}');
  end if;
  return v_code;
end;
$$;

create function public.check_in_session(p_event uuid, p_code text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_session public.event_sessions;
  v_starts timestamptz;
  v_ends timestamptz;
  v_picked uuid;
begin
  if not private.has_permission(p_event, 'event.view') then
    raise exception 'not a member of this event' using errcode = '42501';
  end if;
  perform private.require_network(p_event);
  select s.* into v_session
  from public.session_codes c join public.event_sessions s on s.id = c.session_id
  where c.event_id = p_event and c.code = upper(trim(p_code)) and s.takes_attendance;
  if v_session.id is null then
    raise exception 'that code doesn''t match a session' using errcode = 'P0002';
  end if;

  select coalesce(v_session.starts_at, sl.starts_at), coalesce(v_session.ends_at, sl.ends_at)
  into v_starts, v_ends from public.session_slots sl where sl.id = v_session.slot_id;
  if now() < v_starts - interval '30 minutes' or now() > coalesce(v_ends, v_starts + interval '2 hours') + interval '30 minutes' then
    raise exception 'check-in for % is closed', v_session.name using errcode = '42501';
  end if;

  select session_id into v_picked from public.session_signups
  where slot_id = v_session.slot_id and user_id = v_uid;
  if v_picked is not null and v_picked <> v_session.id then
    raise exception 'you signed up for a different session at this time' using errcode = '22023';
  end if;

  insert into public.session_attendance (event_id, session_id, user_id, method, marked_by)
  values (p_event, v_session.id, v_uid, 'code', v_uid)
  on conflict do nothing;
  perform private.audit(p_event, 'session.checked_in', 'session', v_session.id, '{}');
  return v_session.name;
end;
$$;

create function public.event_attendance(p_event uuid)
returns table (user_id uuid, display_name text, session_id uuid, expected boolean, attended_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.has_permission(p_event, 'sessions.attendance') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
  with expected as (
    select m.user_id, s.id as session_id
    from public.event_members m
    join public.event_sessions s on s.event_id = m.event_id and s.required and s.takes_attendance
    where m.event_id = p_event and m.role = 'participant' and m.status = 'active'
    union
    select g.user_id, g.session_id
    from public.session_signups g join public.event_sessions s on s.id = g.session_id
    where g.event_id = p_event and s.takes_attendance
  ),
  rows as (
    select e.user_id, e.session_id, true as expected from expected e
    union all
    select a.user_id, a.session_id, false from public.session_attendance a
    where a.event_id = p_event
      and not exists (select 1 from expected e where e.user_id = a.user_id and e.session_id = a.session_id)
  )
  select r.user_id, p.display_name, r.session_id, r.expected, a.created_at
  from rows r
  join public.profiles p on p.id = r.user_id
  left join public.session_attendance a on a.session_id = r.session_id and a.user_id = r.user_id
  order by p.display_name;
end;
$$;

grant execute on function
  public.event_agenda(uuid),
  public.save_agenda(uuid, jsonb),
  public.choose_session(uuid),
