create function private.enqueue_email(
  p_org uuid, p_event uuid, p_user uuid, p_to text, p_kind text, p_vars jsonb default '{}'
)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_to text := p_to;
  v_id bigint;
begin
  if v_to is null and p_user is not null then
    select email into v_to from auth.users where id = p_user;
  end if;
  if v_to is null then
    return null;
  end if;
  insert into public.email_outbox (org_id, event_id, user_id, to_email, kind, locale, vars)
  values (p_org, p_event, p_user, v_to, p_kind,
    (select p.locale from public.profiles p where p.id = p_user
       and p.locale ~ '^[a-z]{2,3}(-[A-Za-z0-9]+)*$'),
    coalesce(p_vars, '{}'))
  returning id into v_id;
  return v_id;
end;
$$;
revoke execute on function private.enqueue_email(uuid, uuid, uuid, text, text, jsonb) from anon, authenticated;

create function private.notification_pref(p_user uuid, p_kind text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select up.value -> p_kind from public.user_preferences up
    where up.user_id = p_user and up.namespace = 'notifications' and up.key = 'channels'
  ), '{}');
$$;
revoke execute on function private.notification_pref(uuid, text) from anon, authenticated;

create function private.notify(
  p_users uuid[], p_event uuid, p_kind text, p_title text, p_body text, p_link text,
  p_meta jsonb default '{}', p_email boolean default null
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_event_name text;
  v_def jsonb := private.notification_kind(p_kind);
  v_user uuid;
  v_pref jsonb;
  v_in_app boolean;
  v_email boolean;
  v_count integer := 0;
begin
  select org_id, name into v_org, v_event_name from public.events where id = p_event;
  if v_org is null then
    raise exception 'unknown event' using errcode = '22023';
  end if;
  for v_user in select distinct u from unnest(p_users) as u where u is not null loop
    v_pref := private.notification_pref(v_user, p_kind);
    v_in_app := coalesce((v_pref ->> 'inApp')::boolean, (v_def ->> 'inApp')::boolean, true);
    v_email := case
      when p_email is false then false
      when coalesce((v_def ->> 'transactional')::boolean, false) then true
      when v_pref ? 'email' then (v_pref ->> 'email')::boolean
      else coalesce(p_email, (v_def ->> 'email')::boolean, false)
    end;
    if v_in_app then
      insert into public.notifications (user_id, org_id, event_id, kind, title, body_md, link)
      values (v_user, v_org, p_event, p_kind, p_title, coalesce(p_body, ''), p_link);
      v_count := v_count + 1;
    end if;
    if v_email then
      perform private.enqueue_email(v_org, p_event, v_user, null,
        coalesce(v_def ->> 'emailKind', 'notification'),
        coalesce(p_meta, '{}') || jsonb_strip_nulls(jsonb_build_object(
          'kind', p_kind, 'title', p_title, 'body', p_body, 'path', p_link, 'event', v_event_name)));
    end if;
  end loop;
  return v_count;
end;
$$;
revoke execute on function private.notify(uuid[], uuid, text, text, text, text, jsonb, boolean)
from anon, authenticated;

create function public.notify_event(
  p_event uuid, p_key text, p_kind text, p_users uuid[], p_title text, p_body text,
  p_link text, p_permission text, p_email boolean default null
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_kind text := p_key || '.' || p_kind;
  v_recipients uuid[];
  v_count integer;
begin
  if p_key !~ '^[a-z][a-z0-9-]{1,30}[a-z0-9]$' or p_kind !~ '^[a-z][a-z0-9_-]{0,40}$' then
    raise exception 'bad notification kind' using errcode = '22023';
  end if;
  if not private.plugin_enabled(p_event, p_key) then
    raise exception 'that plugin is not on for this event' using errcode = '42501';
  end if;
  if p_permission is distinct from 'event.manage' and p_permission not like p_key || '.%' then
    raise exception 'name one of the plugin''s own permissions' using errcode = '22023';
  end if;
  if not private.has_permission(p_event, p_permission) then
    raise exception 'not allowed to notify' using errcode = '42501';
  end if;
  if cardinality(p_users) > 200 then
    raise exception 'too many recipients' using errcode = '22023';
  end if;
  if (select count(*) from public.notifications
      where event_id = p_event and kind like p_key || '.%' and created_at > now() - interval '1 hour') > 2000 then
    raise exception 'too many notifications from this plugin; try again later' using errcode = '54000';
  end if;
  select array_agg(m.user_id) into v_recipients
  from public.event_members m
  where m.event_id = p_event and m.status = 'active' and m.user_id = any (p_users);

  v_count := private.notify(v_recipients, p_event, v_kind, p_title, p_body, nullif(p_link, ''), '{}', p_email);
  perform private.audit(p_event, p_key || '.notified', 'notification', null,
    jsonb_build_object('kind', v_kind, 'count', coalesce(cardinality(v_recipients), 0)));
  return v_count;
end;
$$;
grant execute on function public.notify_event(uuid, text, text, uuid[], text, text, text, text, boolean)
to authenticated;

create function public.email_outbox_claim(p_limit integer default 20)
returns setof public.email_outbox
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.role()) is distinct from 'service_role' then
    raise exception 'only the app drains the outbox' using errcode = '42501';
  end if;
  return query
  update public.email_outbox o
  set status = 'sending', attempts = o.attempts + 1, next_attempt_at = now() + interval '10 minutes'
  where o.id in (
    select d.id from public.email_outbox d
    where d.status in ('queued', 'sending') and d.next_attempt_at <= now()
    order by d.next_attempt_at, d.id
    limit greatest(least(p_limit, 100), 1)
    for update skip locked
  )
  returning o.*;
end;
$$;
revoke execute on function public.email_outbox_claim(integer) from authenticated;
grant execute on function public.email_outbox_claim(integer) to service_role;

create function public.email_outbox_finish(
  p_id bigint, p_outcome text, p_error text default null, p_max_attempts integer default 5
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.role()) is distinct from 'service_role' then
    raise exception 'only the app drains the outbox' using errcode = '42501';
  end if;
  if p_outcome not in ('sent', 'skipped', 'retry') then
    raise exception 'unknown outcome "%"', p_outcome using errcode = '22023';
  end if;
  update public.email_outbox o
  set
    status = case
      when p_outcome = 'sent' then 'sent'
      when p_outcome = 'skipped' then 'skipped'
      when o.attempts >= p_max_attempts then 'failed'
      else 'queued'
    end,
    sent_at = case when p_outcome = 'sent' then now() else o.sent_at end,
    last_error = left(p_error, 500),
    next_attempt_at = case
      when p_outcome = 'retry' and o.attempts < p_max_attempts
        then now() + make_interval(mins => (4 ^ greatest(o.attempts - 1, 0))::integer)
      else o.next_attempt_at
    end
  where o.id = p_id;
end;
$$;
revoke execute on function public.email_outbox_finish(bigint, text, text, integer) from authenticated;
grant execute on function public.email_outbox_finish(bigint, text, text, integer) to service_role;

create function private.drain_email_outbox()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_url text := private.instance_setting('tenancy') ->> 'appUrl';
  v_waiting integer;
  v_ts text := extract(epoch from now())::bigint::text;
begin
  if v_url is null then
    return 0;
  end if;
  select count(*) into v_waiting from public.email_outbox
  where status in ('queued', 'sending') and next_attempt_at <= now();
  if v_waiting = 0 then
    return 0;
  end if;
  perform net.http_post(
    url := rtrim(v_url, '/') || '/api/email/drain',
    body := '{}'::jsonb,
    headers := jsonb_build_object(
      'content-type', 'application/json',
      'x-bogey-timestamp', v_ts,
      'x-bogey-signature', encode(extensions.hmac(v_ts, private.email_drain_secret(), 'sha256'), 'hex'))
  );
  return v_waiting;
end;
$$;
revoke execute on function private.drain_email_outbox() from anon, authenticated;

create function private.prune_notifications()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.email_outbox
  where status in ('sent', 'skipped', 'failed') and created_at < now() - interval '30 days';
  delete from public.notifications where created_at < now() - interval '180 days';
$$;
revoke execute on function private.prune_notifications() from anon, authenticated;

create function private.email_outbox_stats()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'queued', count(*) filter (where status in ('queued', 'sending')),
    'oldestQueuedAt', min(created_at) filter (where status in ('queued', 'sending')),
    'failed24h', count(*) filter (where status = 'failed' and created_at > now() - interval '1 day'),
    'lastError', (select o.last_error from public.email_outbox o
                  where o.last_error is not null order by o.id desc limit 1))
  from public.email_outbox;
$$;
revoke execute on function private.email_outbox_stats() from anon, authenticated;

select private.hide_suspended_org('public.notifications');
select private.hide_suspended_org('public.email_outbox');

select cron.schedule('bogey-email-drain', '* * * * *', 'select private.drain_email_outbox()');
select cron.schedule('bogey-prune-notifications', '23 4 * * *', 'select private.prune_notifications()');

-- ─── supabase/schemas/17_checkin.sql ───────────────────────────────────────

create table public.checkins (
  event_id uuid not null,
  user_id uuid not null,
  checked_in_at timestamptz not null default now(),
  checked_in_by uuid references public.profiles on delete set null,
  method text not null check (method in ('desk', 'qr', 'self', 'import')),
  checked_out_at timestamptz,
  note text not null default '' check (length(note) <= 200),
  primary key (event_id, user_id),
  foreign key (event_id, user_id) references public.event_members (event_id, user_id) on delete cascade
);
create index checkins_event_in_idx on public.checkins (event_id, checked_in_at desc);
create index checkins_checked_in_by_fk_idx on public.checkins (checked_in_by);

create table public.member_codes (
  event_id uuid not null,
  user_id uuid not null,
  code text not null unique check (code ~ '^[A-HJ-NP-Z2-9]{8}$'),
  primary key (event_id, user_id),
  foreign key (event_id, user_id) references public.event_members (event_id, user_id) on delete cascade
);

create table public.badge_emails (
  event_id uuid not null,
  user_id uuid not null,
  sent_at timestamptz not null default now(),
  primary key (event_id, user_id),
  foreign key (event_id, user_id) references public.event_members (event_id, user_id) on delete cascade
);

alter table public.checkins enable row level security;
alter table public.member_codes enable row level security;
alter table public.badge_emails enable row level security;

insert into public.role_permissions (role_key, permission) values
  ('staff', 'people.checkin');

create policy checkins_select on public.checkins for select to authenticated
  using (user_id = (select auth.uid()) or (select private.has_permission(event_id, 'people.checkin')));

create function private.checked_in(p_event uuid, p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.checkins where event_id = p_event and user_id = p_user and checked_out_at is null);
$$;
grant execute on function private.checked_in(uuid, uuid) to authenticated;

create function private.check_in_ok(p_event uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select not coalesce((private.event_setting(p_event, 'checkin') ->> 'requiredToCompete')::boolean, false)
    or private.event_role(p_event) is distinct from 'participant'
    or private.checked_in(p_event, (select auth.uid()));
$$;
grant execute on function private.check_in_ok(uuid) to authenticated;

do $$
begin
  if not exists (select 1 from vault.secrets where name = 'bogey:venue-code') then
    perform vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'bogey:venue-code');
  end if;
end;
$$;

create function private.venue_code(p_event uuid, p_back integer default 0)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select upper(substr(encode(extensions.hmac(
    p_event::text || ':' || (floor(extract(epoch from now()) / 600)::bigint - p_back)::text,
    (select decrypted_secret from vault.decrypted_secrets where name = 'bogey:venue-code'),
    'sha256'), 'hex'), 1, 6));
$$;
revoke execute on function private.venue_code(uuid, integer) from anon, authenticated;

create function public.venue_code(p_event uuid)
returns table (code text, seconds_left integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.has_permission(p_event, 'people.checkin') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query select private.venue_code(p_event),
    (600 - (extract(epoch from now())::bigint % 600))::integer;
end;
$$;

create function private.new_member_code()
returns text
language sql
volatile
set search_path = ''
as $$
  select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789', 1 + (get_byte(b, i) % 32), 1), '')
  from (select extensions.gen_random_bytes(8) as b) r, generate_series(0, 7) i;
$$;

create function private.member_code(p_event uuid, p_user uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_code text;
begin
  select code into v_code from public.member_codes where event_id = p_event and user_id = p_user;
  if v_code is not null then
    return v_code;
  end if;
  loop
    begin
      insert into public.member_codes (event_id, user_id, code)
      values (p_event, p_user, private.new_member_code())
      on conflict (event_id, user_id) do nothing;
      select code into v_code from public.member_codes where event_id = p_event and user_id = p_user;
      return v_code;
    exception when unique_violation then
    end;
  end loop;
end;
$$;
revoke execute on function private.member_code(uuid, uuid) from anon, authenticated;

create function public.my_badge(p_event uuid)
returns table (code text, name text, team text, division text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null or private.event_role(p_event) is null then
    raise exception 'not in this event' using errcode = '42501';
  end if;
  return query
  select private.member_code(p_event, v_uid),
    coalesce(p.display_name, 'Participant'),
    (select t.name from public.team_members tm join public.teams t on t.id = tm.team_id
     where tm.event_id = p_event and tm.user_id = v_uid limit 1),
    (select d.name from public.event_members m join public.divisions d on d.id = m.division_id
     where m.event_id = p_event and m.user_id = v_uid)
  from public.profiles p where p.id = v_uid;
end;
$$;

create function public.check_in(
  p_event uuid, p_user uuid default null, p_code text default null, p_method text default 'desk',
  p_note text default ''
)
returns table (user_id uuid, name text, already boolean)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_target uuid;
  v_settings jsonb := private.event_setting(p_event, 'checkin');
  v_already boolean;
begin
  if v_uid is null then
    raise exception 'sign in first' using errcode = '42501';
  end if;
  if p_method not in ('desk', 'qr', 'self', 'import') then
    raise exception 'unknown method' using errcode = '22023';
  end if;

  if p_method = 'self' then
    if coalesce((v_settings ->> 'selfCheckIn')::boolean, false) is not true
       or upper(btrim(coalesce(p_code, ''))) not in (private.venue_code(p_event), private.venue_code(p_event, 1))
       or not private.window_open(p_event, 'checkin')
       or private.event_role(p_event) is null then
      raise exception 'that code doesn''t check you in' using errcode = '42501';
    end if;
    v_target := v_uid;
  else
    if not private.has_permission(p_event, 'people.checkin') then
      raise exception 'not allowed' using errcode = '42501';
    end if;
    if p_user is not null then
      v_target := p_user;
    else
      select c.user_id into v_target from public.member_codes c
      where c.event_id = p_event and c.code = upper(btrim(coalesce(p_code, '')));
    end if;
  end if;

  if v_target is null or not exists (
    select 1 from public.event_members m where m.event_id = p_event and m.user_id = v_target and m.status = 'active'
  ) then
    raise exception 'no one in this event matches' using errcode = 'P0002';
  end if;

  v_already := private.checked_in(p_event, v_target);
  if not v_already then
    insert into public.checkins (event_id, user_id, checked_in_by, method, note)
    values (p_event, v_target, v_uid, p_method, left(coalesce(p_note, ''), 200))
    on conflict on constraint checkins_pkey do update
      set checked_in_at = now(), checked_in_by = v_uid, method = excluded.method,
          checked_out_at = null, note = excluded.note;
    perform private.audit(p_event, 'checkin.checked_in', 'member', v_target,
      jsonb_build_object('method', p_method));
  end if;
  return query select v_target, coalesce(p.display_name, 'Participant'), v_already
    from public.profiles p where p.id = v_target;
end;
$$;

create function public.undo_check_in(p_event uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.has_permission(p_event, 'people.checkin') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  delete from public.checkins where event_id = p_event and user_id = p_user;
  if found then
    perform private.audit(p_event, 'checkin.undone', 'member', p_user, '{}');
  end if;
end;
$$;

create function public.check_out(p_event uuid, p_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.has_permission(p_event, 'people.checkin') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.checkins set checked_out_at = now()
  where event_id = p_event and user_id = p_user and checked_out_at is null;
  if found then
    perform private.audit(p_event, 'checkin.checked_out', 'member', p_user, '{}');
  end if;
end;
$$;

create function public.checkin_roster(p_event uuid)
returns table (
  user_id uuid, name text, email text, role public.event_role, team text, division text,
  checked_in_at timestamptz, checked_out_at timestamptz, method text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not (private.has_permission(p_event, 'people.checkin') or private.can_manage(p_event)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
  select m.user_id, coalesce(p.display_name, 'Participant'), u.email::text, m.role,
    (select t.name from public.team_members tm join public.teams t on t.id = tm.team_id
     where tm.event_id = p_event and tm.user_id = m.user_id limit 1),
    d.name, c.checked_in_at, c.checked_out_at, c.method
  from public.event_members m
  join public.profiles p on p.id = m.user_id
  join auth.users u on u.id = m.user_id
  left join public.divisions d on d.id = m.division_id
  left join public.checkins c on c.event_id = m.event_id and c.user_id = m.user_id
  where m.event_id = p_event and m.status = 'active'
  order by coalesce(p.display_name, ''), u.email;
end;
$$;

create function public.badge_sheet(p_event uuid, p_roles public.event_role[] default array['participant']::public.event_role[])
returns table (user_id uuid, name text, role public.event_role, team text, division text, code text)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not (private.has_permission(p_event, 'people.checkin') or private.can_manage(p_event)) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
  select m.user_id, coalesce(p.display_name, 'Participant'), m.role,
    (select t.name from public.team_members tm join public.teams t on t.id = tm.team_id
     where tm.event_id = p_event and tm.user_id = m.user_id limit 1),
    d.name, private.member_code(p_event, m.user_id)
  from public.event_members m
  join public.profiles p on p.id = m.user_id
  left join public.divisions d on d.id = m.division_id
  where m.event_id = p_event and m.status = 'active' and m.role = any (p_roles)
  order by coalesce(p.display_name, '');
end;
$$;

create function public.check_in_walk_in(p_event uuid, p_email text, p_name text default '')
returns table (registered boolean, checked_in boolean)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := lower(btrim(p_email));
  v_user uuid;
begin
  if not private.has_permission(p_event, 'people.checkin') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if not coalesce((private.event_setting(p_event, 'checkin') ->> 'allowWalkIns')::boolean, false) then
    raise exception 'this event doesn''t take walk-ins' using errcode = '42501';
  end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'that isn''t an email address' using errcode = '22023';
  end if;

  insert into public.registrations (event_id, email, full_name, source, role, status, reviewed_by, reviewed_at)
  values (p_event, v_email, nullif(btrim(p_name), ''), 'import', 'participant', 'approved', (select auth.uid()), now())
  on conflict (event_id, email) do update set status = 'approved'
    where public.registrations.status in ('pending', 'rejected', 'withdrawn');
  perform private.audit(p_event, 'checkin.walk_in', 'registration', null, '{}');

  select u.id into v_user from auth.users u where lower(u.email) = v_email;
  if v_user is not null and exists (
    select 1 from public.event_members m where m.event_id = p_event and m.user_id = v_user and m.status = 'active'
  ) then
    perform public.check_in(p_event, v_user, null, 'desk');
    return query select true, true;
  end if;
  return query select true, false;
end;
$$;

create function private.send_badge_emails()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event record;
  v_hours integer;
  v_person uuid;
  v_count integer := 0;
begin
  for v_event in
    select e.id, e.slug, e.starts_at from public.events e
    where e.starts_at > now() and e.starts_at < now() + interval '14 days' and e.visibility <> 'draft'
  loop
    v_hours := (private.event_setting(v_event.id, 'checkin') ->> 'badgeEmailHours')::integer;
    continue when v_hours is null or v_hours = 0 or v_event.starts_at > now() + make_interval(hours => v_hours);
    for v_person in
      select m.user_id from public.event_members m
      where m.event_id = v_event.id and m.role = 'participant' and m.status = 'active'
        and not exists (select 1 from public.badge_emails b where b.event_id = m.event_id and b.user_id = m.user_id)
    loop
      insert into public.badge_emails (event_id, user_id) values (v_event.id, v_person);
      perform private.notify(array[v_person], v_event.id, 'checkin.badge',
        'Your check-in code', 'Show it at the desk when you arrive.', '/events/' || v_event.slug,
        jsonb_build_object('when', to_char(v_event.starts_at, 'FMDay HH24:MI') || ' UTC'));
      v_count := v_count + 1;
    end loop;
  end loop;
  return v_count;
end;
$$;
revoke execute on function private.send_badge_emails() from anon, authenticated;
select cron.schedule('bogey-badge-emails', '*/10 * * * *', 'select private.send_badge_emails()');

grant execute on function
  public.my_badge(uuid),
  public.check_in(uuid, uuid, text, text, text),
  public.venue_code(uuid),
  public.undo_check_in(uuid, uuid),
  public.check_out(uuid, uuid),
  public.checkin_roster(uuid),
  public.badge_sheet(uuid, public.event_role[]),
  public.check_in_walk_in(uuid, text, text)
to authenticated;

select private.hide_suspended_org('public.checkins');
select private.hide_suspended_org('public.member_codes');
select private.hide_suspended_org('public.badge_emails');

alter publication supabase_realtime add table public.checkins;

-- ─── supabase/schemas/18_api.sql ───────────────────────────────────────────

create table public.calendar_tokens (
  user_id uuid primary key references public.profiles on delete cascade,
  token_hash text not null unique,
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);
alter table public.calendar_tokens enable row level security;
create policy calendar_tokens_select on public.calendar_tokens for select to authenticated
  using (user_id = (select auth.uid()));

create function private.calendar_hash(p_token text)
returns text
language sql
immutable
set search_path = ''
as $$
  select encode(sha256(convert_to(p_token, 'UTF8')), 'hex');
$$;

create function public.create_calendar_token()
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_token text := 'bgc_' || encode(extensions.gen_random_bytes(24), 'hex');
begin
  if (select auth.uid()) is null then
    raise exception 'sign in first' using errcode = '42501';
  end if;
  insert into public.calendar_tokens (user_id, token_hash)
  values ((select auth.uid()), private.calendar_hash(v_token))
  on conflict (user_id) do update set token_hash = excluded.token_hash, created_at = now(), last_used_at = null;
  return v_token;
end;
$$;
revoke execute on function public.create_calendar_token() from public, anon;
grant execute on function public.create_calendar_token() to authenticated;

create function public.revoke_calendar_token()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.calendar_tokens where user_id = (select auth.uid());
$$;
revoke execute on function public.revoke_calendar_token() from public, anon;
grant execute on function public.revoke_calendar_token() to authenticated;

create function public.calendar_feed(p_token text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
begin
  select user_id into v_user from public.calendar_tokens where token_hash = private.calendar_hash(p_token);
  if v_user is null then
    return null;
  end if;
  update public.calendar_tokens set last_used_at = now() where user_id = v_user and (last_used_at is null or last_used_at < now() - interval '1 hour');
  return jsonb_build_object(
    'sessions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', es.id, 'event', e.slug, 'event_name', e.name, 'name', es.name,
        'location', es.location, 'description', es.description_md,
        'starts_at', coalesce(es.starts_at, sl.starts_at), 'ends_at', coalesce(es.ends_at, sl.ends_at))
        order by coalesce(es.starts_at, sl.starts_at))
      from public.event_sessions es
      join public.session_slots sl on sl.id = es.slot_id
      join public.events e on e.id = es.event_id
      join public.event_members m on m.event_id = es.event_id and m.user_id = v_user and m.status = 'active'
      where (exists (select 1 from public.session_signups su where su.session_id = es.id and su.user_id = v_user)
          or exists (select 1 from public.session_hosts h where h.session_id = es.id and h.user_id = v_user))
        and coalesce(e.ends_at, e.starts_at, now()) > now() - interval '30 days'), '[]'),
    'windows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'event', e.slug, 'event_name', e.name, 'key', w.key, 'opens_at', w.opens_at, 'closes_at', w.closes_at)
        order by coalesce(w.opens_at, w.closes_at))
      from public.event_windows w
      join public.events e on e.id = w.event_id
      join public.event_members m on m.event_id = w.event_id and m.user_id = v_user and m.status = 'active'
      where (w.opens_at is not null or w.closes_at is not null)
        and coalesce(e.ends_at, e.starts_at, now()) > now() - interval '30 days'), '[]'));
end;
$$;
revoke execute on function public.calendar_feed(text) from public;
grant execute on function public.calendar_feed(text) to anon, authenticated;

create function public.public_announcements(p_event uuid)
returns table (id uuid, title text, body_md text, severity public.announcement_severity, published_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.is_public_event(p_event) then
    raise exception 'event not found' using errcode = 'P0002';
  end if;
  return query
  select a.id, a.title, a.body_md, a.severity, a.publish_at
  from public.announcements a
  where a.event_id = p_event and a.deleted_at is null and a.everyone and a.publish_at <= now()
  order by a.publish_at desc
  limit 50;
end;
$$;
revoke execute on function public.public_announcements(uuid) from public;
grant execute on function public.public_announcements(uuid) to anon, authenticated;

create function private.webhook_kind(p_action text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_action
    when 'registration.pending' then 'registration.created'
    when 'registration.approved' then 'registration.updated'
    when 'registration.rejected' then 'registration.updated'
    when 'registration.withdrawn' then 'registration.updated'
    when 'registration.waitlisted' then 'registration.updated'
    when 'registration.promoted' then 'registration.updated'
    when 'team.created' then 'team.created'
    when 'submission.submitted' then 'submission.submitted'
    when 'results.published' then 'results.published'
    when 'window.opened' then 'window.opened'
    when 'window.closed' then 'window.closed'
    when 'announcement.posted' then 'announcement.posted'
    when 'checkin.checked_in' then 'checkin.created'
  end;
$$;

create function private.webhook_kinds()
returns text[]
language sql
immutable
set search_path = ''
as $$
  select array['registration.created', 'registration.updated', 'team.created', 'submission.submitted',
    'results.published', 'window.opened', 'window.closed', 'announcement.posted', 'checkin.created'];
$$;

create function private.webhook_url_ok(p_url text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_url ~* '^https://[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(:[0-9]{1,5})?(/[^\s]*)?$'
    and length(p_url) <= 500
    and split_part(split_part(substr(p_url, 9), '/', 1), ':', 1) !~* '(^|\.)(localhost|local|internal|lan|home|corp)$'
    and split_part(split_part(substr(p_url, 9), '/', 1), ':', 1) !~ '^[0-9.]+$';
$$;

create table public.webhooks (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.orgs on delete cascade,
  event_id uuid,
  url text not null check (private.webhook_url_ok(url)),
  events text[] not null check (cardinality(events) between 1 and 9 and events <@ private.webhook_kinds()),
  disabled_at timestamptz,
  created_by uuid references public.profiles on delete set null,
  created_at timestamptz not null default now(),
  foreign key (event_id) references public.events on delete cascade
);
create index webhooks_org_id_idx on public.webhooks (org_id, event_id);
create index webhooks_event_id_fk_idx on public.webhooks (event_id);
create index webhooks_created_by_fk_idx on public.webhooks (created_by);
alter table public.webhooks enable row level security;
create policy webhooks_select on public.webhooks for select to authenticated
  using ((select private.is_org_admin(org_id)) or (event_id is not null and (select private.can_manage(event_id))));

create table public.webhook_secrets (
  webhook_id uuid primary key references public.webhooks on delete cascade,
  secret text not null
);
alter table public.webhook_secrets enable row level security;

create table public.webhook_deliveries (
  id uuid primary key default gen_random_uuid(),
  webhook_id uuid not null references public.webhooks on delete cascade,
  org_id uuid not null,
  event_id uuid,
  kind text not null,
  payload jsonb not null,
  status text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed')),
  attempts integer not null default 0,
  request_id bigint,
  sent_at timestamptz,
  response_status integer,
  last_error text check (length(last_error) <= 500),
  next_attempt_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  delivered_at timestamptz
);
create index webhook_deliveries_webhook_id_idx on public.webhook_deliveries (webhook_id, created_at desc);
create index webhook_deliveries_due_idx on public.webhook_deliveries (next_attempt_at) where status = 'queued';
create index webhook_deliveries_sending_idx on public.webhook_deliveries (sent_at) where status = 'sending';
create index webhook_deliveries_org_id_idx on public.webhook_deliveries (org_id);
alter table public.webhook_deliveries enable row level security;
create policy webhook_deliveries_select on public.webhook_deliveries for select to authenticated
  using ((select private.is_org_admin(org_id)) or (event_id is not null and (select private.can_manage(event_id))));

create function private.can_manage_webhook(p_org uuid, p_event uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select case when p_event is null then private.is_org_admin(p_org)
    else private.is_org_admin(p_org) or private.can_manage(p_event) end;
$$;
revoke execute on function private.can_manage_webhook(uuid, uuid) from public, anon, authenticated;

create function public.create_webhook(
  p_org uuid, p_event uuid default null, p_url text default null, p_events text[] default null
)
returns table (webhook_id uuid, secret text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_secret text := 'whsec_' || encode(extensions.gen_random_bytes(24), 'hex');
begin
  if p_event is not null and not exists (select 1 from public.events e where e.id = p_event and e.org_id = p_org) then
    raise exception 'that event is not in this organization' using errcode = '22023';
  end if;
  if not private.can_manage_webhook(p_org, p_event) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if nullif(btrim(p_url), '') is null or coalesce(cardinality(p_events), 0) = 0 then
    raise exception 'a webhook needs an address and at least one kind' using errcode = '22023';
  end if;
  if (select count(*) from public.webhooks w where w.org_id = p_org) >= 25 then
    raise exception 'an organization can have 25 webhooks' using errcode = '54000';
  end if;
  insert into public.webhooks (org_id, event_id, url, events, created_by)
  values (p_org, p_event, btrim(p_url), p_events, (select auth.uid()))
  returning id into v_id;
  insert into public.webhook_secrets (webhook_id, secret) values (v_id, v_secret);
  if p_event is not null then
    perform private.audit(p_event, 'webhook.created', 'webhook', v_id, jsonb_build_object('events', p_events));
  else
    perform private.audit_org(p_org, 'webhook.created', 'webhook', v_id, jsonb_build_object('events', p_events));
  end if;
  return query select v_id, v_secret;
end;
$$;
revoke execute on function public.create_webhook(uuid, uuid, text, text[]) from public, anon;
grant execute on function public.create_webhook(uuid, uuid, text, text[]) to authenticated;

create function public.update_webhook(p_id uuid, p_url text, p_events text[], p_disabled boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_hook public.webhooks;
begin
  select * into v_hook from public.webhooks where id = p_id;
  if v_hook.id is null or not private.can_manage_webhook(v_hook.org_id, v_hook.event_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.webhooks set url = btrim(p_url), events = p_events,
    disabled_at = case when p_disabled then coalesce(disabled_at, now()) end
  where id = p_id;
  if p_disabled then
    update public.webhook_deliveries set status = 'failed', last_error = 'webhook disabled'
    where webhook_id = p_id and status = 'queued';
  end if;
  if v_hook.event_id is not null then
    perform private.audit(v_hook.event_id, 'webhook.updated', 'webhook', p_id, jsonb_build_object('disabled', p_disabled));
  else
    perform private.audit_org(v_hook.org_id, 'webhook.updated', 'webhook', p_id, jsonb_build_object('disabled', p_disabled));
  end if;
end;
$$;
revoke execute on function public.update_webhook(uuid, text, text[], boolean) from public, anon;
grant execute on function public.update_webhook(uuid, text, text[], boolean) to authenticated;

create function public.delete_webhook(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_hook public.webhooks;
begin
  select * into v_hook from public.webhooks where id = p_id;
  if v_hook.id is null or not private.can_manage_webhook(v_hook.org_id, v_hook.event_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  delete from public.webhooks where id = p_id;
  if v_hook.event_id is not null then
    perform private.audit(v_hook.event_id, 'webhook.deleted', 'webhook', p_id, '{}');
  else
    perform private.audit_org(v_hook.org_id, 'webhook.deleted', 'webhook', p_id, '{}');
  end if;
end;
$$;
revoke execute on function public.delete_webhook(uuid) from public, anon;
grant execute on function public.delete_webhook(uuid) to authenticated;

create function public.rotate_webhook_secret(p_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_hook public.webhooks;
  v_secret text := 'whsec_' || encode(extensions.gen_random_bytes(24), 'hex');
begin
  select * into v_hook from public.webhooks where id = p_id;
  if v_hook.id is null or not private.can_manage_webhook(v_hook.org_id, v_hook.event_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.webhook_secrets set secret = v_secret where webhook_id = p_id;
  if v_hook.event_id is not null then
    perform private.audit(v_hook.event_id, 'webhook.secret_rotated', 'webhook', p_id, '{}');
  else
    perform private.audit_org(v_hook.org_id, 'webhook.secret_rotated', 'webhook', p_id, '{}');
  end if;
  return v_secret;
end;
$$;
revoke execute on function public.rotate_webhook_secret(uuid) from public, anon;
grant execute on function public.rotate_webhook_secret(uuid) to authenticated;

create function public.resend_webhook_delivery(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.webhook_deliveries;
begin
  select * into v_row from public.webhook_deliveries where id = p_id;
  if v_row.id is null or not private.can_manage_webhook(v_row.org_id, v_row.event_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  update public.webhook_deliveries set status = 'queued', attempts = 0, next_attempt_at = now(), last_error = null
  where id = p_id and status in ('sent', 'failed');
end;
$$;
revoke execute on function public.resend_webhook_delivery(uuid) from public, anon;
grant execute on function public.resend_webhook_delivery(uuid) to authenticated;

create function private.queue_webhooks(
  p_org uuid, p_event uuid, p_kind text, p_action text, p_target_type text, p_target_id uuid,
  p_meta jsonb, p_at timestamptz
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event public.events;
begin
  select * into v_event from public.events where id = p_event;
  insert into public.webhook_deliveries (webhook_id, org_id, event_id, kind, payload)
  select w.id, w.org_id, p_event, p_kind, jsonb_build_object(
    'kind', p_kind, 'action', p_action, 'at', p_at,
    'event', jsonb_build_object('id', v_event.id, 'slug', v_event.slug, 'name', v_event.name),
    'target', jsonb_build_object('type', p_target_type, 'id', p_target_id),
    'data', p_meta)
  from public.webhooks w
  where w.org_id = p_org and (w.event_id is null or w.event_id = p_event)
    and w.disabled_at is null and p_kind = any (w.events);
end;
$$;
revoke execute on function private.queue_webhooks(uuid, uuid, text, text, text, uuid, jsonb, timestamptz)
  from public, anon, authenticated;

create function private.webhook_from_audit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_kind text := private.webhook_kind(new.action);
begin
  -- A scheduled announcement is sent when it goes live, by deliver_webhooks.
  if v_kind is null or new.event_id is null or coalesce((new.meta ->> 'scheduled')::boolean, false) then
    return null;
  end if;
  perform private.queue_webhooks(new.org_id, new.event_id, v_kind, new.action, new.target_type,
    new.target_id, new.meta, new.created_at);
  return null;
exception when others then
  return null;
end;
$$;
create trigger audit_log_webhooks after insert on public.audit_log
  for each row execute function private.webhook_from_audit();

create function private.webhook_format(p_url text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_url ~* '^https://((ptb|canary)\.)?discord(app)?\.com/api/webhooks/' then 'discord'
    when p_url ~* '^https://hooks\.slack\.com/' then 'slack'
    else 'json'
  end;
$$;

create function private.webhook_summary(p_payload jsonb, p_quote text)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_data jsonb := coalesce(p_payload -> 'data', '{}');
  -- Anything people typed is quoted for the chat service, so it can't add links or formatting.
  v_name text := case when p_quote is null then coalesce(v_data ->> 'name', '')
    else regexp_replace(coalesce(v_data ->> 'name', ''), p_quote, '\\\1', 'g') end;
  v_title text := case when p_quote is null then coalesce(v_data ->> 'title', '')
    else regexp_replace(coalesce(v_data ->> 'title', ''), p_quote, '\\\1', 'g') end;
  v_window text := case when p_quote is null then coalesce(v_data ->> 'key', '')
    else regexp_replace(coalesce(v_data ->> 'key', ''), p_quote, '\\\1', 'g') end;
begin
  return case p_payload ->> 'action'
    when 'registration.pending' then 'Someone registered and is waiting for review.'
    when 'registration.approved' then 'A registration was approved.'
    when 'registration.rejected' then 'A registration was declined.'
    when 'registration.withdrawn' then 'Someone withdrew their registration.'
    when 'registration.waitlisted' then 'Someone joined the waitlist.'
    when 'registration.promoted' then 'Someone moved up from the waitlist.'
    when 'team.created' then format('Team "%s" was created.', v_name)
    when 'submission.submitted' then 'A project was submitted.'
    when 'results.published' then 'Results are published.'
    when 'window.opened' then format('The %s window opened.', v_window)
    when 'window.closed' then format('The %s window closed.', v_window)
    when 'announcement.posted' then case
      when coalesce((v_data ->> 'everyone')::boolean, false) then format('Announcement: %s', v_title)
      else 'An announcement was posted.'
    end
    when 'checkin.checked_in' then 'Someone checked in.'
    else p_payload ->> 'kind'
  end;
end;
$$;

-- Discord and Slack take their own message shape; every other address gets the signed JSON.
create function private.webhook_body(p_url text, p_payload jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_format text := private.webhook_format(p_url);
  v_base text;
  v_link text;
  v_text text;
begin
  if v_format = 'json' then
    return p_payload;
  end if;
  select 'https://' || d.hostname into v_base from public.org_domains d
  join public.events e on e.org_id = d.org_id
  where e.id = (p_payload #>> '{event,id}')::uuid and d.is_primary;
  v_base := rtrim(coalesce(v_base, private.instance_setting('tenancy') ->> 'appUrl', ''), '/');
  if v_base <> '' then
    v_link := v_base || '/events/' || (p_payload #>> '{event,slug}');
  end if;
  if v_format = 'discord' then
    v_text := format('**%s** · %s',
      regexp_replace(p_payload #>> '{event,name}', '([\\*_~`|>#\[\]()<@-])', '\\\1', 'g'),
      private.webhook_summary(p_payload, '([\\*_~`|>#\[\]()<@-])'));
    if v_link is not null then
      v_text := v_text || E'\n<' || v_link || '>';
    end if;
    return jsonb_build_object('content', left(v_text, 2000),
      'allowed_mentions', jsonb_build_object('parse', '[]'::jsonb));
  end if;
  v_text := format('*%s* · %s',
    replace(replace(replace(p_payload #>> '{event,name}', '&', '&amp;'), '<', '&lt;'), '>', '&gt;'),
    replace(replace(replace(private.webhook_summary(p_payload, null), '&', '&amp;'), '<', '&lt;'), '>', '&gt;'));
  if v_link is not null then
    v_text := v_text || E'\n<' || v_link || '|Open the event>';
  end if;
  return jsonb_build_object('text', v_text);
end;
$$;
revoke execute on function private.webhook_body(text, jsonb) from public, anon, authenticated;

create function private.queue_due_announcement_webhooks()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row record;
begin
  for v_row in
    select a.id, a.event_id, a.title, a.everyone, a.publish_at, e.org_id
    from public.announcements a
    join public.events e on e.id = a.event_id
    where a.deleted_at is null
      and a.publish_at > a.created_at
      and a.publish_at <= now()
      and a.publish_at > now() - interval '1 hour'
      and not exists (
        select 1 from public.webhook_deliveries d
        where d.kind = 'announcement.posted' and d.payload #>> '{target,id}' = a.id::text
      )
  loop
    perform private.queue_webhooks(v_row.org_id, v_row.event_id, 'announcement.posted',
      'announcement.posted', 'announcement', v_row.id,
      jsonb_build_object('title', v_row.title, 'everyone', v_row.everyone), v_row.publish_at);
  end loop;
end;
$$;
revoke execute on function private.queue_due_announcement_webhooks() from public, anon, authenticated;

create function private.deliver_webhooks()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row record;
  v_response record;
  v_body text;
  v_ts text;
  v_secret text;
  v_url text;
  v_request bigint;
  v_count integer := 0;
  v_delays constant integer[] := array[1, 5, 30, 120, 720];
  v_payload jsonb;
begin
  perform private.queue_due_announcement_webhooks();

  for v_row in
    select d.id, d.request_id, d.attempts, d.sent_at from public.webhook_deliveries d
    where d.status = 'sending' for update skip locked
  loop
    select r.status_code, r.error_msg, r.content into v_response from net._http_response r where r.id = v_row.request_id;
    if v_response is null and v_row.sent_at > now() - interval '10 minutes' then
      continue;
    end if;
    if v_response.status_code between 200 and 299 then
      update public.webhook_deliveries set status = 'sent', delivered_at = now(), response_status = v_response.status_code,
        last_error = null where id = v_row.id;
    elsif v_response.status_code between 400 and 499 and v_response.status_code not in (408, 429) then
      -- The address refused this request; sending it again won't change the answer.
      update public.webhook_deliveries set status = 'failed', response_status = v_response.status_code,
        last_error = left('answered ' || v_response.status_code
          || coalesce(': ' || nullif(btrim(v_response.content), ''), ''), 500)
      where id = v_row.id;
    else
      update public.webhook_deliveries set
        status = case when attempts >= 6 then 'failed' else 'queued' end,
        next_attempt_at = now() + make_interval(mins => v_delays[least(attempts, 5)]),
        response_status = v_response.status_code,
        last_error = left(coalesce(v_response.error_msg, case when v_response.status_code is null then 'no response' else 'answered ' || v_response.status_code end), 500)
      where id = v_row.id;
    end if;
  end loop;

  for v_row in
    select d.id, d.webhook_id, d.kind, d.payload from public.webhook_deliveries d
    join public.webhooks w on w.id = d.webhook_id and w.disabled_at is null
    where d.status = 'queued' and d.next_attempt_at <= now()
    order by d.next_attempt_at limit 50 for update of d skip locked
  loop
    select w.url, s.secret into v_url, v_secret from public.webhooks w
    join public.webhook_secrets s on s.webhook_id = w.id where w.id = v_row.webhook_id;
    v_payload := private.webhook_body(v_url, v_row.payload);
    v_body := v_payload::text;
    v_ts := extract(epoch from now())::bigint::text;
    select net.http_post(
      url := v_url,
      body := v_payload,
      headers := jsonb_build_object(
        'content-type', 'application/json',
        'user-agent', 'Bogey-Webhook/1',
        'x-bogey-event', v_row.kind,
        'x-bogey-delivery', v_row.id::text,
        'x-bogey-timestamp', v_ts,
        'x-bogey-signature', 'sha256=' || encode(extensions.hmac(v_ts || '.' || v_body, v_secret, 'sha256'), 'hex')),
      timeout_milliseconds := 10000) into v_request;
    update public.webhook_deliveries set status = 'sending', attempts = attempts + 1, request_id = v_request, sent_at = now()
    where id = v_row.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
revoke execute on function private.deliver_webhooks() from public, anon, authenticated;

create function private.prune_webhook_deliveries()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.webhook_deliveries where created_at < now() - interval '30 days';
$$;
revoke execute on function private.prune_webhook_deliveries() from public, anon, authenticated;

select private.hide_suspended_org('public.webhooks');
select private.hide_suspended_org('public.webhook_deliveries');

select cron.schedule('bogey-webhooks', '* * * * *', 'select private.deliver_webhooks()');
select cron.schedule('bogey-prune-webhooks', '41 4 * * *', 'select private.prune_webhook_deliveries()');

create function public.event_archive_people(p_event uuid)
returns table (user_id uuid, email text, display_name text)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_org uuid;
begin
  select e.org_id into v_org from public.events e where e.id = p_event;
  if v_org is null or not ((select auth.role()) = 'service_role' or private.is_org_admin(v_org)) then
    raise exception 'only organization admins can archive an event' using errcode = '42501';
  end if;
  return query
  select m.user_id, u.email::text, p.display_name
  from public.event_members m
  join public.profiles p on p.id = m.user_id
  join auth.users u on u.id = m.user_id
  where m.event_id = p_event
  order by p.display_name;
end;
$$;
revoke execute on function public.event_archive_people(uuid) from public, anon;
grant execute on function public.event_archive_people(uuid) to authenticated, service_role;

create function public.portfolios_enabled()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (private.instance_setting('accounts') ->> 'portfolios')::boolean is true;
$$;
revoke execute on function public.portfolios_enabled() from public;
grant execute on function public.portfolios_enabled() to authenticated;

create function public.public_profile(p_handle text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_profile public.profiles;
begin
  if public.portfolios_enabled() is not true then
    return null;
  end if;
  select * into v_profile from public.profiles where handle = p_handle::extensions.citext;
  if v_profile.id is null then
    return null;
  end if;
  if v_profile.visibility <> 'public' and v_profile.id is distinct from (select auth.uid())
    and not private.shares_org(v_profile.id) then
    return null;
  end if;
  return jsonb_build_object(
    'name', v_profile.display_name,
    'handle', v_profile.handle,
    'avatarPath', v_profile.avatar_path,
    'pronouns', v_profile.pronouns,
    'bio', v_profile.bio_md,
    'links', v_profile.links,
    'visibility', v_profile.visibility,
    'projects', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'title', s.title, 'team', t.name, 'event', e.slug, 'eventName', e.name, 'submittedAt', s.submitted_at)
        order by s.submitted_at desc)
      from public.team_members tm
      join public.submissions s on s.team_id = tm.team_id and s.status = 'submitted' and s.is_public
      join public.teams t on t.id = s.team_id
      join public.events e on e.id = s.event_id
      where tm.user_id = v_profile.id and private.gallery_open(s.event_id)), '[]'),
    'awards', coalesce((
      select jsonb_agg(jsonb_build_object(
        'kind', a.kind, 'label', a.label, 'place', a.place, 'project', s.title, 'event', e.slug, 'eventName', e.name)
        order by e.starts_at desc nulls last, a.sort)
      from public.team_members tm
      join public.awards a on a.submission_id is not null
      join public.submissions s on s.id = a.submission_id and s.team_id = tm.team_id
      join public.events e on e.id = a.event_id
      where tm.user_id = v_profile.id and private.is_public_event(a.event_id)
        and private.latest_publication(a.event_id) is not null), '[]'),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object('slug', e.slug, 'name', e.name, 'startsAt', e.starts_at)
        order by e.starts_at desc nulls last)
      from public.checkins c
      join public.events e on e.id = c.event_id
      where c.user_id = v_profile.id and private.is_public_event(e.id)), '[]'));
end;
$$;
revoke execute on function public.public_profile(text) from public;
grant execute on function public.public_profile(text) to anon, authenticated;

-- ─── supabase/schemas/19_certificates.sql ──────────────────────────────────

create table public.certificate_templates (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.orgs on delete cascade,
  event_id uuid references public.events on delete cascade,
  kind text not null check (kind in ('participation', 'award', 'judge', 'volunteer')),
  body_md text not null check (length(body_md) between 1 and 2000),
  orientation text not null default 'landscape' check (orientation in ('landscape', 'portrait')),
  background_url text check (background_url ~ '^https://' and length(background_url) <= 500),
  updated_at timestamptz not null default now()
);
create unique index certificate_templates_event_kind_idx on public.certificate_templates (event_id, kind) where event_id is not null;
create unique index certificate_templates_org_kind_idx on public.certificate_templates (org_id, kind) where event_id is null;
create index certificate_templates_event_id_fk_idx on public.certificate_templates (event_id);
alter table public.certificate_templates enable row level security;
create policy certificate_templates_select on public.certificate_templates for select to authenticated
  using ((select private.is_org_admin(org_id)) or (event_id is not null and (select private.can_manage(event_id))));

create table public.certificates (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events on delete cascade,
  user_id uuid not null references public.profiles on delete cascade,
  kind text not null check (kind in ('participation', 'award', 'judge', 'volunteer')),
  award_id uuid references public.awards on delete set null,
  label text not null default '' check (length(label) <= 140),
  recipient_name text not null check (length(recipient_name) between 1 and 80),
  code text not null unique check (code ~ '^[A-HJ-NP-Z2-9]{10}$'),
  issued_by uuid references public.profiles on delete set null,
  issued_at timestamptz not null default now(),
  revoked_at timestamptz
);
create unique index certificates_person_idx on public.certificates
  (event_id, user_id, kind, coalesce(award_id, '00000000-0000-0000-0000-000000000000'::uuid));
create index certificates_user_id_idx on public.certificates (user_id);
create index certificates_award_id_fk_idx on public.certificates (award_id);
create index certificates_issued_by_fk_idx on public.certificates (issued_by);
alter table public.certificates enable row level security;
create policy certificates_select on public.certificates for select to authenticated
  using (user_id = (select auth.uid()) or (select private.can_manage(event_id)));

select private.hide_suspended_org('public.certificate_templates');
select private.hide_suspended_org('public.certificates');

create function private.certificate_code()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  c_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_bytes bytea := extensions.gen_random_bytes(10);
  v_code text := '';
begin
  for v_i in 0 .. 9 loop
    v_code := v_code || substr(c_alphabet, (get_byte(v_bytes, v_i) % 32) + 1, 1);
  end loop;
  return v_code;
end;
$$;

create function private.certificate_options(p_event uuid, p_user uuid)
returns table (kind text, award_id uuid, label text)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_role public.event_role;
begin
  if not coalesce((private.event_setting(p_event, 'certificates') ->> 'enabled')::boolean, false) then
    return;
  end if;
  select m.role into v_role from public.event_members m
  where m.event_id = p_event and m.user_id = p_user and m.status = 'active';
  if v_role is null then
    return;
  end if;
  if v_role = 'participant' then
    if exists (select 1 from public.checkins c where c.event_id = p_event and c.user_id = p_user)
      or exists (
        select 1 from public.submissions s
        join public.team_members tm on tm.team_id = s.team_id and tm.user_id = p_user
        where s.event_id = p_event and s.status = 'submitted') then
      return query select 'participation'::text, null::uuid, ''::text;
    end if;
    if private.latest_publication(p_event) is not null then
      return query
      select 'award'::text, a.id, a.label
      from public.awards a
      join public.submissions s on s.id = a.submission_id
      join public.team_members tm on tm.team_id = s.team_id and tm.user_id = p_user
      where a.event_id = p_event;
    end if;
  elsif v_role = 'judge' then
    return query select 'judge'::text, null::uuid, ''::text;
  elsif v_role = 'staff' then
    return query select 'volunteer'::text, null::uuid, ''::text;
  end if;
end;
$$;
revoke execute on function private.certificate_options(uuid, uuid) from public, anon, authenticated;

create function private.issue_certificate(p_event uuid, p_user uuid, p_kind text, p_award uuid, p_label text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_code text;
  v_name text;
begin
  select c.code into v_code from public.certificates c
  where c.event_id = p_event and c.user_id = p_user and c.kind = p_kind
    and c.award_id is not distinct from p_award and c.revoked_at is null;
  if v_code is not null then
    return v_code;
  end if;
  select display_name into v_name from public.profiles where id = p_user;
  delete from public.certificates c
  where c.event_id = p_event and c.user_id = p_user and c.kind = p_kind and c.award_id is not distinct from p_award;
  loop
    v_code := private.certificate_code();
    begin
      insert into public.certificates (event_id, user_id, kind, award_id, label, recipient_name, code, issued_by)
      values (p_event, p_user, p_kind, p_award, p_label, v_name, v_code, (select auth.uid()));
      return v_code;
    exception when unique_violation then
      if exists (select 1 from public.certificates c
        where c.event_id = p_event and c.user_id = p_user and c.kind = p_kind and c.award_id is not distinct from p_award) then
        raise;
      end if;
    end;
  end loop;
end;
$$;
revoke execute on function private.issue_certificate(uuid, uuid, text, uuid, text) from public, anon, authenticated;

create function public.my_certificates(p_event uuid)
returns table (kind text, award_id uuid, label text, code text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return query
  select o.kind, o.award_id, o.label,
    (select c.code from public.certificates c
     where c.event_id = p_event and c.user_id = (select auth.uid()) and c.kind = o.kind
       and c.award_id is not distinct from o.award_id and c.revoked_at is null)
  from private.certificate_options(p_event, (select auth.uid())) o
  order by o.kind, o.label;
end;
$$;
revoke execute on function public.my_certificates(uuid) from public, anon;
grant execute on function public.my_certificates(uuid) to authenticated;

create function public.claim_certificate(p_event uuid, p_kind text, p_award uuid default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_option record;
begin
  select * into v_option from private.certificate_options(p_event, (select auth.uid())) o
  where o.kind = p_kind and o.award_id is not distinct from p_award;
  if v_option.kind is null then
    raise exception 'there is no such certificate for you yet' using errcode = '42501';
  end if;
  return private.issue_certificate(p_event, (select auth.uid()), v_option.kind, v_option.award_id, v_option.label);
end;
$$;
revoke execute on function public.claim_certificate(uuid, text, uuid) from public, anon;
grant execute on function public.claim_certificate(uuid, text, uuid) to authenticated;

create function public.issue_certificates(p_event uuid, p_kinds text[] default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_person record;
  v_option record;
  v_before text;
  v_count integer := 0;
  v_slug text;
begin
  if not private.can_manage(p_event) then
    raise exception 'only organizers can issue certificates' using errcode = '42501';
  end if;
  select slug into v_slug from public.events where id = p_event;
  for v_person in select m.user_id from public.event_members m where m.event_id = p_event and m.status = 'active' loop
    for v_option in select * from private.certificate_options(p_event, v_person.user_id) o
      where p_kinds is null or o.kind = any (p_kinds)
    loop
      select c.code into v_before from public.certificates c
      where c.event_id = p_event and c.user_id = v_person.user_id and c.kind = v_option.kind
        and c.award_id is not distinct from v_option.award_id and c.revoked_at is null;
      if v_before is null then
        perform private.issue_certificate(p_event, v_person.user_id, v_option.kind, v_option.award_id, v_option.label);
        v_count := v_count + 1;
        perform private.notify(array[v_person.user_id], p_event, 'certificate.issued',
          'Your certificate is ready', '', '/events/' || v_slug || '/certificates', '{}');
      end if;
    end loop;
  end loop;
  perform private.audit(p_event, 'certificate.issued', 'event', p_event, jsonb_build_object('count', v_count));
  return v_count;
end;
$$;
revoke execute on function public.issue_certificates(uuid, text[]) from public, anon;
grant execute on function public.issue_certificates(uuid, text[]) to authenticated;

create function public.revoke_certificate(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event uuid;
begin
  select event_id into v_event from public.certificates where id = p_id;
  if v_event is null or not private.can_manage(v_event) then
    raise exception 'only organizers can revoke certificates' using errcode = '42501';
  end if;
  update public.certificates set revoked_at = now() where id = p_id and revoked_at is null;
  perform private.audit(v_event, 'certificate.revoked', 'certificate', p_id, '{}');
end;
$$;
revoke execute on function public.revoke_certificate(uuid) from public, anon;
grant execute on function public.revoke_certificate(uuid) to authenticated;

create function public.save_certificate_template(
  p_org uuid, p_event uuid, p_kind text, p_body_md text, p_orientation text default 'landscape', p_background_url text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_event is null then
    if not private.is_org_admin(p_org) then
      raise exception 'only organization admins can edit the organization''s certificates' using errcode = '42501';
    end if;
  else
    if not exists (select 1 from public.events e where e.id = p_event and e.org_id = p_org) then
      raise exception 'that event is not in this organization' using errcode = '22023';
    end if;
    if not private.can_manage(p_event) then
      raise exception 'only organizers can edit certificates' using errcode = '42501';
    end if;
  end if;
  if btrim(coalesce(p_body_md, '')) = '' then
    delete from public.certificate_templates t
    where t.org_id = p_org and t.event_id is not distinct from p_event and t.kind = p_kind;
  elsif p_event is null then
    insert into public.certificate_templates (org_id, event_id, kind, body_md, orientation, background_url)
    values (p_org, null, p_kind, p_body_md, p_orientation, nullif(btrim(p_background_url), ''))
    on conflict (org_id, kind) where event_id is null do update set
      body_md = excluded.body_md, orientation = excluded.orientation, background_url = excluded.background_url, updated_at = now();
  else
    insert into public.certificate_templates (org_id, event_id, kind, body_md, orientation, background_url)
    values (p_org, p_event, p_kind, p_body_md, p_orientation, nullif(btrim(p_background_url), ''))
    on conflict (event_id, kind) where event_id is not null do update set
      body_md = excluded.body_md, orientation = excluded.orientation, background_url = excluded.background_url, updated_at = now();
  end if;
  if p_event is not null then
    perform private.audit(p_event, 'certificate.template_saved', 'event', p_event, jsonb_build_object('kind', p_kind));
  else
    perform private.audit_org(p_org, 'certificate.template_saved', 'org', p_org, jsonb_build_object('kind', p_kind));
  end if;
end;
$$;
revoke execute on function public.save_certificate_template(uuid, uuid, text, text, text, text) from public, anon;
grant execute on function public.save_certificate_template(uuid, uuid, text, text, text, text) to authenticated;

create function private.certificate_json(p_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'code', c.code, 'name', c.recipient_name, 'kind', c.kind, 'label', c.label,
    'issuedAt', c.issued_at, 'revoked', c.revoked_at is not null,
    'event', e.name, 'eventSlug', e.slug, 'startsAt', e.starts_at, 'endsAt', e.ends_at, 'org', o.name,
    'body', t.body_md, 'orientation', coalesce(t.orientation, 'landscape'), 'background', t.background_url)
  from public.certificates c
  join public.events e on e.id = c.event_id
  join public.orgs o on o.id = e.org_id
  left join lateral (
    select ct.body_md, ct.orientation, ct.background_url from public.certificate_templates ct
    where ct.org_id = e.org_id and ct.kind = c.kind and (ct.event_id = e.id or ct.event_id is null)
    order by ct.event_id is null limit 1) t on true
  where c.id = p_id;
$$;
revoke execute on function private.certificate_json(uuid) from public, anon, authenticated;

create function public.verify_certificate(p_code text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select private.certificate_json(c.id) from public.certificates c where c.code = upper(btrim(p_code));
$$;
revoke execute on function public.verify_certificate(text) from public;
grant execute on function public.verify_certificate(text) to anon, authenticated;

create function public.event_certificates(p_event uuid)
returns setof jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.can_manage(p_event) then
    raise exception 'only organizers can print certificates' using errcode = '42501';
  end if;
  return query
  select private.certificate_json(c.id) from public.certificates c
  where c.event_id = p_event and c.revoked_at is null order by c.recipient_name, c.kind;
end;
$$;
revoke execute on function public.event_certificates(uuid) from public, anon;
grant execute on function public.event_certificates(uuid) to authenticated;

-- ─── supabase/schemas/20_plugins.sql ───────────────────────────────────────

create table private.plugin_objects (
  seq bigint generated by default as identity primary key,
  plugin text not null check (plugin ~ '^[a-z][a-z0-9-]{1,30}[a-z0-9]$'),
  kind text not null,
  names text[] not null,
  args text[] not null default '{}',
  identity text not null,
  recorded_at timestamptz not null default now(),
  unique (kind, names, args)
);
create index plugin_objects_plugin_idx on private.plugin_objects (plugin);
revoke all on private.plugin_objects from public, anon, authenticated, service_role;

create function private.plugin_catalog()
returns table (key text, classid oid, objid oid, kind text, identity text, fingerprint text)
language plpgsql
stable
set search_path = ''
as $$
begin
  return query
  with ns as (
    select n.oid from pg_catalog.pg_namespace n
    where n.nspname not in ('pg_catalog', 'information_schema')
      and n.nspname !~ '^pg_(toast|temp_|toast_temp_)'
  ),
  objects (classid, objid, fingerprint) as (
    select 'pg_catalog.pg_namespace'::regclass::oid, n.oid, md5(concat_ws('|', n.nspowner, n.nspacl::text))
    from pg_catalog.pg_namespace n where n.oid in (select oid from ns)
    union all
    select 'pg_catalog.pg_class'::regclass::oid, c.oid, md5(concat_ws('|',
      c.relkind, c.relowner, c.relrowsecurity, c.relforcerowsecurity, c.relreplident, c.relacl::text, c.reloptions::text,
      (select string_agg(concat_ws(':', a.attname, a.atttypid, a.atttypmod, a.attnotnull, a.attisdropped,
          a.attidentity, a.attgenerated, pg_catalog.pg_get_expr(d.adbin, d.adrelid), a.attacl::text), ',' order by a.attnum)
       from pg_catalog.pg_attribute a
       left join pg_catalog.pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
       where a.attrelid = c.oid and a.attnum > 0),
      (select string_agg(con.conname || ' ' || pg_catalog.pg_get_constraintdef(con.oid), ',' order by con.conname)
       from pg_catalog.pg_constraint con where con.conrelid = c.oid),
      case when c.relkind in ('v', 'm') then pg_catalog.pg_get_viewdef(c.oid)
           when c.relkind in ('i', 'I') then pg_catalog.pg_get_indexdef(c.oid) end))
    from pg_catalog.pg_class c
    where c.relnamespace in (select oid from ns) and c.relkind in ('r', 'p', 'v', 'm', 'S', 'f', 'c', 'i', 'I')
    union all
    select 'pg_catalog.pg_proc'::regclass::oid, p.oid, md5(concat_ws('|',
      p.proowner, p.prokind, p.prosecdef, p.provolatile, p.proisstrict, p.proleakproof, p.prorettype,
      p.proargtypes::text, p.prosrc, p.probin, p.proconfig::text, p.proacl::text))
    from pg_catalog.pg_proc p where p.pronamespace in (select oid from ns)
    union all
    select 'pg_catalog.pg_type'::regclass::oid, t.oid, md5(concat_ws('|', t.typowner, t.typacl::text, t.typdefault, t.typnotnull,
      (select string_agg(e.enumlabel, ',' order by e.enumsortorder) from pg_catalog.pg_enum e where e.enumtypid = t.oid),
      (select string_agg(con.conname || ' ' || pg_catalog.pg_get_constraintdef(con.oid), ',' order by con.conname)
       from pg_catalog.pg_constraint con where con.contypid = t.oid)))
    from pg_catalog.pg_type t where t.typnamespace in (select oid from ns) and t.typtype in ('d', 'e', 'r', 'm')
    union all
    select 'pg_catalog.pg_policy'::regclass::oid, po.oid, md5(concat_ws('|', po.polcmd, po.polpermissive, po.polroles::text,
      pg_catalog.pg_get_expr(po.polqual, po.polrelid), pg_catalog.pg_get_expr(po.polwithcheck, po.polrelid)))
    from pg_catalog.pg_policy po
    union all
    select 'pg_catalog.pg_trigger'::regclass::oid, tg.oid, md5(concat_ws('|', tg.tgenabled, pg_catalog.pg_get_triggerdef(tg.oid)))
    from pg_catalog.pg_trigger tg where not tg.tgisinternal
    union all
    select 'pg_catalog.pg_rewrite'::regclass::oid, r.oid, md5(pg_catalog.pg_get_ruledef(r.oid))
    from pg_catalog.pg_rewrite r where r.rulename <> '_RETURN'
    union all
    select 'pg_catalog.pg_publication_rel'::regclass::oid, pr.oid, '' from pg_catalog.pg_publication_rel pr
    union all
    select 'pg_catalog.pg_extension'::regclass::oid, x.oid, x.extversion from pg_catalog.pg_extension x
    union all
    select 'pg_catalog.pg_event_trigger'::regclass::oid, et.oid, md5(concat_ws('|', et.evtevent, et.evtfoid, et.evtenabled))
    from pg_catalog.pg_event_trigger et
  )
  select o.classid::text || ':' || o.objid::text, o.classid, o.objid, i.type, i.identity, o.fingerprint
  from objects o
  cross join lateral pg_catalog.pg_identify_object(o.classid, o.objid, 0) i
  where not exists (
    select 1 from pg_catalog.pg_depend d where d.classid = o.classid and d.objid = o.objid and d.deptype = 'e'
  );

  if pg_catalog.to_regclass('cron.job') is not null then
    return query execute $q$
      select 'cron job:' || j.jobname, null::oid, null::oid, 'cron job', j.jobname::text,
        md5(concat_ws('|', j.schedule, j.command, j.database, j.username, j.active))
      from cron.job j where j.jobname is not null
    $q$;
  end if;
  if pg_catalog.to_regclass('storage.buckets') is not null then
    return query execute $q$
      select 'storage bucket:' || b.id, null::oid, null::oid, 'storage bucket', b.id::text,
        md5(concat_ws('|', b.public, b.file_size_limit, b.allowed_mime_types::text))
      from storage.buckets b
    $q$;
  end if;
end;
$$;

create function private.plugin_recorded()
returns table (key text, plugin text, seq bigint)
language plpgsql
stable
set search_path = ''
as $$
declare
  v_row private.plugin_objects;
  v_classid oid;
  v_objid oid;
begin
  for v_row in select * from private.plugin_objects order by seq loop
    if v_row.kind in ('cron job', 'storage bucket') then
      key := v_row.kind || ':' || v_row.names[1];
    else
      begin
        select a.classid, a.objid into v_classid, v_objid
        from pg_catalog.pg_get_object_address(v_row.kind, v_row.names, v_row.args) a;
      exception when others then
        continue;
      end;
      key := v_classid::text || ':' || v_objid::text;
    end if;
    plugin := v_row.plugin;
    seq := v_row.seq;
    return next;
  end loop;
end;
$$;

create function private.plugin_owners()
returns table (key text, plugin text, seq bigint)
language sql
stable
set search_path = ''
as $$
  with recursive recorded as (
    select * from private.plugin_recorded()
  ),
  tree (classid, objid, plugin) as (
    select split_part(r.key, ':', 1)::oid, split_part(r.key, ':', 2)::oid, r.plugin
    from recorded r where r.key ~ '^\d+:\d+$'
    union
    select d.classid, d.objid, t.plugin
    from pg_catalog.pg_depend d
    join tree t on d.refclassid = t.classid and d.refobjid = t.objid
    where d.deptype in ('a', 'i')
  )
  select r.key, r.plugin, r.seq from recorded r
  union all
  select distinct on (k.key) k.key, k.plugin, null::bigint
  from (select t.classid::text || ':' || t.objid::text as key, t.plugin from tree t) k
  where not exists (select 1 from recorded r where r.key = k.key);
$$;

create function private.plugin_object_name(p_identity text)
returns text
language sql
immutable
set search_path = ''
as $$
  select regexp_replace(regexp_replace(split_part(p_identity, '(', 1), '^.*\.', ''), '"', '', 'g');
$$;

create function private.plugin_migration_begin(p_plugin text)
returns void
language plpgsql
set search_path = ''
as $$
begin
  if p_plugin !~ '^[a-z][a-z0-9-]{1,30}[a-z0-9]$' then
    raise exception 'not a plugin key: %', p_plugin using errcode = '22023';
  end if;
  if current_setting('transaction_isolation') <> 'repeatable read' then
    raise exception 'run a plugin migration in a repeatable read transaction (begin isolation level repeatable read)'
      using errcode = '25000';
  end if;
  if coalesce(current_setting('bogey.plugin_migration', true), '') <> '' then
    raise exception 'a migration of % is still open in this transaction', current_setting('bogey.plugin_migration')
      using errcode = '25000';
  end if;
  perform set_config('bogey.plugin_migration', p_plugin, true);

  create temp table bogey_plugin_before on commit drop as select * from private.plugin_catalog();
  create temp table bogey_plugin_owners on commit drop as select * from private.plugin_owners();
end;
$$;

create function private.plugin_migration_end(
  p_plugin text, p_requires text[] default '{}', p_shared jsonb default '{}'
)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_problems text[];
begin
  if coalesce(current_setting('bogey.plugin_migration', true), '') is distinct from p_plugin then
    raise exception 'call private.plugin_migration_begin(%) first', quote_literal(p_plugin) using errcode = '25000';
  end if;

  create temp table bogey_plugin_after on commit drop as select * from private.plugin_catalog();

  select array_agg(format('%s %s %s, which belongs to %s',
           case when a.key is null then 'dropped' else 'changed' end, b.kind, b.identity,
           coalesce('the ' || o.plugin || ' plugin', 'Bogey')) order by b.identity)
  into v_problems
  from pg_temp.bogey_plugin_before b
  left join pg_temp.bogey_plugin_after a on a.key = b.key
  left join pg_temp.bogey_plugin_owners o on o.key = b.key
  where (a.key is null or a.fingerprint <> b.fingerprint)
    and o.plugin is distinct from p_plugin;

  create temp table bogey_plugin_added on commit drop as
    select a.* from pg_temp.bogey_plugin_after a
    where not exists (select 1 from pg_temp.bogey_plugin_before b where b.key = a.key);

  v_problems := coalesce(v_problems, '{}') || coalesce((
    select array_agg(format('created extension %s: an instance installs extensions, not a plugin (say what it needs in its README)', x.identity))
    from pg_temp.bogey_plugin_added x where x.kind = 'extension'), '{}');

  create temp table bogey_plugin_tree on commit drop as
    with recursive tree (classid, objid) as (
      select x.classid, x.objid from pg_temp.bogey_plugin_added x where x.classid is not null
      union
      select split_part(o.key, ':', 1)::oid, split_part(o.key, ':', 2)::oid
      from pg_temp.bogey_plugin_owners o where o.plugin = p_plugin and o.key ~ '^\d+:\d+$'
      union
      select d.classid, d.objid
      from pg_catalog.pg_depend d
      join tree t on d.refclassid = t.classid and d.refobjid = t.objid
      where d.deptype in ('a', 'i')
    )
    select t.classid, t.objid, t.classid::text || ':' || t.objid::text as key from tree t;

  create temp table bogey_plugin_dependents on commit drop as
    select t.key from pg_temp.bogey_plugin_tree t
    where exists (
      select 1 from pg_catalog.pg_depend d
      join pg_temp.bogey_plugin_tree p on d.refclassid = p.classid and d.refobjid = p.objid
      where d.classid = t.classid and d.objid = t.objid and d.deptype in ('a', 'i')
    );

  v_problems := v_problems || coalesce((
    select array_agg(distinct format('%s builds on %s of the %s plugin, which %s', i.identity, f.identity, o.plugin,
             case when not o.plugin = any (p_requires) then 'it doesn''t list in `requires`'
                  else 'that plugin doesn''t list in `shares.sql`' end))
    from pg_temp.bogey_plugin_tree t
    join pg_catalog.pg_depend d on d.classid = t.classid and d.objid = t.objid and d.deptype in ('n', 'a')
    join pg_temp.bogey_plugin_owners o on o.key = d.refclassid::text || ':' || d.refobjid::text and o.seq is not null
    join pg_temp.bogey_plugin_after f on f.key = o.key
    cross join lateral pg_catalog.pg_identify_object(t.classid, t.objid, 0) i
    where o.plugin <> p_plugin
      and not (o.plugin = any (p_requires)
               and coalesce(p_shared -> o.plugin, '[]') ? private.plugin_object_name(f.identity))), '{}');

  v_problems := v_problems || coalesce((
    select array_agg(distinct format('%s names %s of the %s plugin, which %s', x.identity, f.identity, o.plugin,
             case when not o.plugin = any (p_requires) then 'it doesn''t list in `requires`'
                  else 'that plugin doesn''t list in `shares.sql`' end))
    from pg_temp.bogey_plugin_after x
    join pg_catalog.pg_proc p on x.classid = 'pg_catalog.pg_proc'::regclass and p.oid = x.objid
    join pg_temp.bogey_plugin_owners o on o.plugin <> p_plugin and o.seq is not null
    join pg_temp.bogey_plugin_after f on f.key = o.key and f.kind in ('table', 'view', 'materialized view', 'function', 'procedure', 'type', 'sequence')
    where (not exists (select 1 from pg_temp.bogey_plugin_before b where b.key = x.key)
           or exists (select 1 from pg_temp.bogey_plugin_before b where b.key = x.key and b.fingerprint <> x.fingerprint))
      and p.prosrc ~* ('\m' || private.plugin_object_name(f.identity) || '\M')
      and not (o.plugin = any (p_requires)
               and coalesce(p_shared -> o.plugin, '[]') ? private.plugin_object_name(f.identity))), '{}');

  if cardinality(v_problems) > 0 then
    raise exception 'the % plugin''s migration can only add to Bogey and change what it made itself:%',
      p_plugin, E'\n  - ' || array_to_string(v_problems, E'\n  - ')
      using errcode = '42501',
            hint = 'Keep the plugin''s data in its own tables, keyed by Bogey''s ids, and its logic in its own functions. See docs/plugins.md#the-database.';
  end if;

  create temp table bogey_plugin_record on commit drop as
    select o.seq, a.key, a.classid, a.objid, a.kind, a.identity
    from pg_temp.bogey_plugin_after a
    left join pg_temp.bogey_plugin_owners o on o.key = a.key and o.plugin = p_plugin and o.seq is not null
    where (o.key is not null)
       or (exists (select 1 from pg_temp.bogey_plugin_added x where x.key = a.key)
           and not exists (select 1 from pg_temp.bogey_plugin_dependents d where d.key = a.key));

  delete from private.plugin_objects where plugin = p_plugin;
  insert into private.plugin_objects (seq, plugin, kind, names, args, identity)
  overriding system value
  select r.seq, p_plugin, r.kind, array[r.identity], '{}', r.identity
  from pg_temp.bogey_plugin_record r where r.classid is null and r.seq is not null;
  insert into private.plugin_objects (seq, plugin, kind, names, args, identity)
  overriding system value
  select r.seq, p_plugin, addr.type, addr.object_names, addr.object_args, r.identity
  from pg_temp.bogey_plugin_record r
  cross join lateral pg_catalog.pg_identify_object_as_address(r.classid, r.objid, 0) addr
  where r.classid is not null and r.seq is not null;
  insert into private.plugin_objects (plugin, kind, names, args, identity)
  select p_plugin, coalesce(addr.type, r.kind), coalesce(addr.object_names, array[r.identity]),
    coalesce(addr.object_args, '{}'), r.identity
  from pg_temp.bogey_plugin_record r
  left join lateral pg_catalog.pg_identify_object_as_address(r.classid, r.objid, 0) addr on r.classid is not null
  where r.seq is null
  order by r.classid is null, r.objid;
  perform setval(pg_catalog.pg_get_serial_sequence('private.plugin_objects', 'seq'),
    greatest((select max(seq) from private.plugin_objects), 1));

  drop table pg_temp.bogey_plugin_before, pg_temp.bogey_plugin_after, pg_temp.bogey_plugin_owners,
    pg_temp.bogey_plugin_added, pg_temp.bogey_plugin_tree, pg_temp.bogey_plugin_dependents, pg_temp.bogey_plugin_record;
  perform set_config('bogey.plugin_migration', '', true);
end;
$$;

create function private.plugin_adopt(p_plugin text, p_objects jsonb)
returns setof text
language plpgsql
set search_path = ''
as $$
declare
  v_item jsonb;
  v_key text;
  v_found record;
begin
  if p_plugin !~ '^[a-z][a-z0-9-]{1,30}[a-z0-9]$' then
    raise exception 'not a plugin key: %', p_plugin using errcode = '22023';
  end if;
  create temp table bogey_adopt_owners on commit drop as select * from private.plugin_owners();
  create temp table bogey_adopt_catalog on commit drop as select * from private.plugin_catalog();

  for v_item in select * from jsonb_array_elements(p_objects) loop
    for v_found in
      select c.* from pg_temp.bogey_adopt_catalog c
      where case v_item ->> 'kind'
        when 'relation' then c.classid = 'pg_catalog.pg_class'::regclass and exists (
          select 1 from pg_catalog.pg_class r where r.oid = c.objid
            and r.relname = v_item ->> 'name' and r.relnamespace::regnamespace::text = v_item ->> 'schema')
        when 'function' then c.classid = 'pg_catalog.pg_proc'::regclass and exists (
          select 1 from pg_catalog.pg_proc p where p.oid = c.objid
            and p.proname = v_item ->> 'name' and p.pronamespace::regnamespace::text = v_item ->> 'schema')
        when 'type' then c.classid = 'pg_catalog.pg_type'::regclass and exists (
          select 1 from pg_catalog.pg_type t where t.oid = c.objid
            and t.typname = v_item ->> 'name' and t.typnamespace::regnamespace::text = v_item ->> 'schema')
        when 'policy' then c.classid = 'pg_catalog.pg_policy'::regclass and exists (
          select 1 from pg_catalog.pg_policy p join pg_catalog.pg_class r on r.oid = p.polrelid
          where p.oid = c.objid and p.polname = v_item ->> 'name' and r.relname = v_item ->> 'table'
            and r.relnamespace::regnamespace::text = v_item ->> 'schema')
        when 'trigger' then c.classid = 'pg_catalog.pg_trigger'::regclass and exists (
          select 1 from pg_catalog.pg_trigger t join pg_catalog.pg_class r on r.oid = t.tgrelid
          where t.oid = c.objid and t.tgname = v_item ->> 'name' and r.relname = v_item ->> 'table'
            and r.relnamespace::regnamespace::text = v_item ->> 'schema')
        when 'publication relation' then c.classid = 'pg_catalog.pg_publication_rel'::regclass and exists (
          select 1 from pg_catalog.pg_publication_rel pr join pg_catalog.pg_class r on r.oid = pr.prrelid
          join pg_catalog.pg_publication pb on pb.oid = pr.prpubid
          where pr.oid = c.objid and pb.pubname = v_item ->> 'name' and r.relname = v_item ->> 'table'
            and r.relnamespace::regnamespace::text = v_item ->> 'schema')
        when 'cron job' then c.key = 'cron job:' || (v_item ->> 'name')
        when 'storage bucket' then c.key = 'storage bucket:' || (v_item ->> 'name')
        when 'schema' then c.classid = 'pg_catalog.pg_namespace'::regclass and c.identity = quote_ident(v_item ->> 'name')
        else false
      end
    loop
      continue when exists (select 1 from pg_temp.bogey_adopt_owners o where o.key = v_found.key);
      continue when v_found.classid is not null and exists (
        select 1 from pg_catalog.pg_depend d
        join pg_temp.bogey_adopt_catalog p on p.classid = d.refclassid and p.objid = d.refobjid
        where d.classid = v_found.classid and d.objid = v_found.objid and d.deptype in ('a', 'i')
          and exists (select 1 from pg_temp.bogey_adopt_owners o where o.key = p.key and o.plugin = p_plugin));
      if v_found.classid is null then
        insert into private.plugin_objects (plugin, kind, names, identity)
        values (p_plugin, v_found.kind, array[v_found.identity], v_found.identity)
        on conflict do nothing;
      else
        insert into private.plugin_objects (plugin, kind, names, args, identity)
        select p_plugin, a.type, a.object_names, a.object_args, v_found.identity
        from pg_catalog.pg_identify_object_as_address(v_found.classid, v_found.objid, 0) a
        on conflict do nothing;
      end if;
      if found then
        insert into pg_temp.bogey_adopt_owners values (v_found.key, p_plugin, null);
        return next v_found.kind || ' ' || v_found.identity;
      end if;
    end loop;
  end loop;
  drop table pg_temp.bogey_adopt_owners, pg_temp.bogey_adopt_catalog;
end;
$$;

create function private.plugin_removal(p_plugin text)
returns table (kind text, identity text, problem text)
language plpgsql
stable
set search_path = ''
as $$
begin
  return query
  with owners as (select * from private.plugin_owners()),
  mine as (select o.key from owners o where o.plugin = p_plugin),
  recorded as (
    select po.seq, po.kind, po.identity, r.key
    from private.plugin_objects po
    left join private.plugin_recorded() r on r.seq = po.seq
    where po.plugin = p_plugin
  )
  select r.kind, r.identity, case when r.key is null then 'already gone' end
  from recorded r
  union all
  select i.type, i.identity, format('depends on %s; it belongs to %s', string_agg(distinct ri.identity, ', '),
           coalesce('the ' || min(o.plugin) || ' plugin', 'Bogey'))
  from pg_catalog.pg_depend d
  cross join lateral pg_catalog.pg_identify_object(d.classid, d.objid, 0) i
  cross join lateral pg_catalog.pg_identify_object(d.refclassid, d.refobjid, 0) ri
  left join owners o on o.key = d.classid::text || ':' || d.objid::text
  where d.refclassid::text || ':' || d.refobjid::text in (select key from mine)
    and d.classid::text || ':' || d.objid::text not in (select key from mine)
    and d.deptype = 'n'
  group by i.type, i.identity;
end;
$$;

create function private.plugin_purge(p_plugin text)
returns setof text
language plpgsql
set search_path = ''
as $$
declare
  v_prefix text := p_plugin || '.';
  v_count bigint;
begin
  if p_plugin !~ '^[a-z][a-z0-9-]{1,30}[a-z0-9]$' then
    raise exception 'not a plugin key: %', p_plugin using errcode = '22023';
  end if;

  delete from public.settings
  where namespace = 'plugin.' || p_plugin or starts_with(namespace, 'plugin.' || v_prefix);
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s settings %s', v_count, case when v_count = 1 then 'row' else 'rows' end); end if;

  update public.settings
  set value = value
    || case when value ? 'enabled' and jsonb_typeof(value -> 'enabled') = 'array'
         then jsonb_build_object('enabled', (value -> 'enabled') - p_plugin) else '{}' end
    || case when value ? 'available' and jsonb_typeof(value -> 'available') = 'array'
         then jsonb_build_object('available', (value -> 'available') - p_plugin) else '{}' end
  where namespace = 'plugins' and (value -> 'enabled' ? p_plugin or value -> 'available' ? p_plugin);
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('turned it off in %s %s', v_count, case when v_count = 1 then 'org or event' else 'orgs and events' end); end if;

  update public.settings
  set value = jsonb_set(value, '{templates}', coalesce((
    select jsonb_object_agg(t.key, t.value) from jsonb_each(value -> 'templates') t
    where not starts_with(t.key, v_prefix)), '{}'))
  where namespace = 'email' and jsonb_typeof(value -> 'templates') = 'object'
    and exists (select 1 from jsonb_object_keys(value -> 'templates') k where starts_with(k, v_prefix));
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted its email wording in %s %s', v_count, case when v_count = 1 then 'place' else 'places' end); end if;

  delete from public.roles where source = p_plugin;
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s %s and who had %s', v_count, case when v_count = 1 then 'role' else 'roles' end, case when v_count = 1 then 'it' else 'them' end); end if;

  delete from public.role_permissions where starts_with(permission, v_prefix);
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s %s granted to roles', v_count, case when v_count = 1 then 'permission' else 'permissions' end); end if;

  delete from public.event_windows where starts_with(key, v_prefix);
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s agenda %s', v_count, case when v_count = 1 then 'window' else 'windows' end); end if;

  delete from private.window_states where starts_with(key, v_prefix);

  delete from public.ranking_inputs where starts_with(provider, v_prefix);
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s ranking %s', v_count, case when v_count = 1 then 'score' else 'scores' end); end if;

  delete from public.notifications where starts_with(kind, v_prefix);
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s %s', v_count, case when v_count = 1 then 'notification' else 'notifications' end); end if;

  delete from public.email_outbox where starts_with(kind, v_prefix) and status in ('queued', 'failed');
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s unsent %s', v_count, case when v_count = 1 then 'email' else 'emails' end); end if;

  delete from public.user_preferences where namespace = p_plugin;
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('deleted %s personal %s', v_count, case when v_count = 1 then 'preference' else 'preferences' end); end if;

  update public.user_preferences
  set value = coalesce((select jsonb_object_agg(c.key, c.value) from jsonb_each(value) c
                        where not starts_with(c.key, v_prefix)), '{}')
  where namespace = 'notifications' and key = 'channels' and jsonb_typeof(value) = 'object'
    and exists (select 1 from jsonb_object_keys(value) k where starts_with(k, v_prefix));

  update public.org_limit_overrides
  set limits = coalesce((select jsonb_object_agg(l.key, l.value) from jsonb_each(limits) l
                         where not starts_with(l.key, v_prefix)), '{}')
  where exists (select 1 from jsonb_object_keys(limits) k where starts_with(k, v_prefix));
  get diagnostics v_count = row_count;
  if v_count > 0 then return next format('cleared limits set for %s %s', v_count, case when v_count = 1 then 'org' else 'orgs' end); end if;
end;
$$;

create function private.plugin_remove(p_plugin text)
returns setof text
language plpgsql
set search_path = ''
as $$
declare
  v_row record;
  v_classid oid;
  v_objid oid;
  v_identity text;
  v_problems text[];
  v_statement text;
begin
  if p_plugin !~ '^[a-z][a-z0-9-]{1,30}[a-z0-9]$' then
    raise exception 'not a plugin key: %', p_plugin using errcode = '22023';
  end if;

  select array_agg(r.identity || ' ' || r.problem) into v_problems
  from private.plugin_removal(p_plugin) r where r.problem is not null and r.problem <> 'already gone';
  if cardinality(v_problems) > 0 then
    raise exception 'the % plugin can''t be removed while something else builds on it:%',
      p_plugin, E'\n  - ' || array_to_string(v_problems, E'\n  - ')
      using errcode = '2BP01', hint = 'Remove the plugins that need it first.';
  end if;

  for v_row in select * from private.plugin_objects where plugin = p_plugin order by seq desc loop
    v_statement := null;
    if v_row.kind = 'cron job' then
      if pg_catalog.to_regclass('cron.job') is not null then
        execute 'select count(*) from cron.job where jobname = $1' into v_objid using v_row.names[1];
        if v_objid > 0 then
          execute 'select cron.unschedule($1)' using v_row.names[1];
          return next 'unscheduled cron job ' || v_row.names[1];
        end if;
      end if;
      continue;
    elsif v_row.kind = 'storage bucket' then
      if pg_catalog.to_regclass('storage.buckets') is not null then
        execute 'select count(*) from storage.objects where bucket_id = $1' into v_objid using v_row.names[1];
        if v_objid > 0 then
          raise exception 'the storage bucket % still holds % files', v_row.names[1], v_objid
            using errcode = '2BP01', hint = 'Empty it through the Storage API (bogey plugins remove does) and try again.';
        end if;
        perform set_config('storage.allow_delete_query', 'true', true);
        execute 'delete from storage.buckets where id = $1' using v_row.names[1];
        perform set_config('storage.allow_delete_query', 'false', true);
        if found then return next 'deleted storage bucket ' || v_row.names[1]; end if;
      end if;
      continue;
    end if;

    begin
      select a.classid, a.objid into v_classid, v_objid
      from pg_catalog.pg_get_object_address(v_row.kind, v_row.names, v_row.args) a;
    exception when others then
      continue;
    end;
    select i.identity into v_identity from pg_catalog.pg_identify_object(v_classid, v_objid, 0) i;
    continue when v_identity is null;

    v_statement := case
      when v_row.kind = 'publication relation' then
        format('alter publication %I drop table %s', v_row.args[1], v_row.names[1] || '.' || v_row.names[2])
      when v_row.kind = 'type' and (select t.typtype from pg_catalog.pg_type t where t.oid = v_objid) = 'd' then
        'drop domain ' || v_identity || ' cascade'
      when v_row.kind = 'composite type' then 'drop type ' || v_identity || ' cascade'
      when v_row.kind in ('table', 'view', 'materialized view', 'sequence', 'index', 'foreign table', 'schema',
                          'function', 'procedure', 'aggregate', 'type', 'policy', 'trigger', 'rule') then
        format('drop %s %s cascade', v_row.kind, v_identity)
    end;
    if v_statement is null then
      raise exception 'don''t know how to remove % %', v_row.kind, v_identity using errcode = '0A000';
    end if;
    execute v_statement;
    return next 'dropped ' || v_row.kind || ' ' || v_identity;
  end loop;

  return query select p.line from private.plugin_purge(p_plugin) p(line);

  delete from private.plugin_objects where plugin = p_plugin;
  if pg_catalog.to_regclass('supabase_migrations.plugin_migrations') is not null then
    execute 'delete from supabase_migrations.plugin_migrations where plugin = $1' using p_plugin;
  end if;
end;
$$;

revoke all on function
  private.plugin_catalog(),
  private.plugin_recorded(),
  private.plugin_owners(),
  private.plugin_object_name(text),
  private.plugin_migration_begin(text),
  private.plugin_migration_end(text, text[], jsonb),
  private.plugin_adopt(text, jsonb),
  private.plugin_removal(text),
  private.plugin_purge(text),
  private.plugin_remove(text)
from public, anon, authenticated, service_role;

